(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">مقطعك. توزيعهم.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">مقطوعتك.</span>","hero.cycle":"مقطوعتك.|مساراتك المنفصلة.|ملف MIDI الخاص بك.","hero.sub":"حوّل مقطعًا متكررًا من 8 مازورات إلى مقطوعة مكتملة ومُوزَّعة بأسلوب أي فنان أو منتج أو نوع موسيقي — تُعزف مباشرةً في الـ DAW الخاص بك، ثم تُسحب إلى الخارج كمسارات صوتية منفصلة أو كقالب أغنية MIDI. مجاني، بلا اتصال، وخالٍ من الذكاء الاصطناعي بنسبة 100%.","hero.chipStandalone":"مستقل","hero.chipWeb":"تطبيق ويب","what.title":"ما هو","what.p1":"المقطع الذي يبدو مكتملًا عند المازورة 8 يظل مقطعًا متكررًا عند المازورة 64. وتحويله إلى مقطوعة يعني ساعات من الكتم والنسخ والقص والأتمتة — المقدمة، واللوازم، والانقطاعات، والتبديلات المفاجئة — قبل أن تسمع ما إذا كانت الفكرة صامدة.","what.p2":"يوزّعه Freally Unloop نيابةً عنك. ضعه على المسار الذي يعزف مقطعك، واختر فنانًا أو منتجًا أو نوعًا موسيقيًا، واضغط تشغيل: يعزف Unloop المقطوعة كاملة فوق صوتك أنت، بتزامن مع مشروعك، على طريقة توزيع ذلك الاسم.","what.p3":"ثم تصبح المقطوعة ملكك. حرّرها مقطعًا مقطعًا، واحتفظ بما يعجبك وأعد سحب الباقي، وصيّرها — مزيجًا أو ملفًا لكل جزء — لتسحبها مباشرةً إلى مساراتك.","how.title":"كيف يعمل","how.loop.title":"كرّره.","how.loop.body":"تتكرر مازوراتك الـ 8 في الـ DAW — أو أفلِت مسارات منفصلة أو مقطع MIDI في التطبيق المستقل أو تطبيق الويب.","how.name.title":"اختر اسمًا.","how.name.body":"ابحث بين 2,413 فنانًا ومنتجًا ونوعًا موسيقيًا واختر نمطًا: يمكن توزيع كل نوع موسيقي بعدة طرق.","how.play.title":"اضغط تشغيل.","how.play.body":"يعزف Unloop المقطوعة كاملة فوق صوتك أنت — المقدمات، واللوازم، والانقطاعات، وقطع 808، والتصاعدات المتقطعة، وإيقاف الشريط، وتبديلات الإيقاع — بتزامن تام مع مشروعك.","how.shape.title":"شكّله.","how.shape.body":"انقل المقاطع وانسخها وقسّمها وطبّق عليها التلاشي، وحرّك المُخفِتات، وارسم الأتمتة، واقفل ما يعجبك وأعد سحب الباقي.","how.take.title":"خذه.","how.take.body":"اسحب المقطوعة المُوزَّعة إلى الخارج بصيغة WAV أو AIFF أو FLAC أو MP3 — مزيجًا أو مسارات منفصلة — أو كقالب أغنية MIDI متعدد المسارات.","docs.language.title":"اللغات","docs.language.p1":"يتحدث Unloop ثماني عشرة لغة. يبدأ بلغة نظامك؛ ولاختيار لغة أخرى، افتح «الإعدادات» من زر الترس واختر واحدة.","ladder.title":"الطريق إلى 1.0","ladder.intro":"سطر واحد لكل إصدار. هذا هو السلّم نفسه الذي تتبعه الخطة الخاصة — إن تحرّك أحدهما تحرّك الآخر، وتقارنهما بوابة بناء.","ladder.rung.v0.1.0":"يُحمَّل المكوّن الإضافي (CLAP وVST3 وAU) والتطبيق المستقل ويمرّران الصوت؛ هيكل المحرّر، ورموز التصميم، و18 لغة، وكل بوابات الجودة، وCI محلي على Windows وLinux، ومدقّقات المكوّنات الإضافية، واختبارات المتصفح.","ladder.rung.v0.2.0":"يتحوّل أيٌّ من 2,413 فنانًا ومنتجًا ونوعًا موسيقيًا إلى خطة توزيع حتمية، مع عدة أنماط لكل نوع.","ladder.rung.v0.3.0":"نسخة واحدة على إيقاع متكرر تعزف المقطوعة كاملة مباشرةً — بلا طقطقات، وبلا أي تأخير، وبتزامن مع الـ DAW الخاص بك.","ladder.rung.v0.4.0":"نسخة لكل جزء، تُقاد كمقطوعة واحدة، مع وحدة التحكم الكاملة.","ladder.rung.v0.5.0":"الالتقاط، والمعاينة داخل Unloop، والتصيير إلى WAV/AIFF/FLAC/MP3، والسحب إلى الخارج، ومشاريع المقاطع، ومكتبة المقاطع — تصفّح مقاطعك واستمع إليها وقصّها، وأعد فتح المشاريع الأخيرة — أول منتج مكتمل: الـ MVP.","ladder.rung.v0.6.0":"نقل المقاطع ونسخها وتقسيمها وتغيير حجمها؛ التلاشي والمُخفِتات والأتمتة؛ القفل وإعادة السحب؛ تراجع وإعادة بلا حدود؛ رفّ التوزيعات وملفات .unarr؛ كل تعديل من لوحة المفاتيح.","ladder.rung.v0.6.5":"مقابض ومُخفِتات وأزرار مُصيَّرة في Blender، وخمسة أشكال بالوضعين الفاتح والداكن، وأصوات للواجهة، وشريط عنوان داكن — كلها واحدة في كل تطبيقات Freally.","ladder.rung.v0.7.0":"تحويل الصوت إلى MIDI، وإدخال مقاطع MIDI، وقالب أغنية MIDI، وطبيب قوة العزف، وسحب MIDI إلى الخارج.","ladder.rung.v0.8.0":"وضع المسارات المنفصلة في التطبيق المستقل وتطبيق الويب، والالتزام بالإيقاع، وطبيب المقاطع.","ladder.rung.v0.9.0":"إعادة التخيّل، ومؤثرات انتقال مُركَّبة، وتبديلات الإيقاع، وطبيب التوزيع، والقوالب، وتعلّم MIDI.","ladder.rung.v0.10.0":"كل نوع موسيقي بعدة أنماط، ومئات من أبرز الفنانين والمنتجين، وكل اسم يُطابَق بأمانة.","ladder.rung.v1.0.0b":"اكتمال الميزات: الحالات الحدّية، وإمكانية الوصول، و18 لغة، وميزانيات الأداء، ومُثبِّتات لثلاثة أنظمة.","ladder.rung.v1.0.0-rc":"مراجعة شاملة من الألف إلى الياء مع إصلاح كل خطأ، ثم اختبار يدوي في برامج DAW حقيقية على كل نظام متاح — مع اكتمال تطبيق الويب وهذا الموقع.","ladder.rung.v1.0.0":"تُفتح التنزيلات، ويُطلَق تطبيق الويب.","ladder.rung.v1.1.0":"عمق التنويعات.","ladder.rung.v1.2.0":"عمق الحركات.","ladder.rung.v1.3.0":"توزيع يراعي الغناء.","ladder.rung.v1.4.0":"الأداء والـ DJ.","ladder.rung.v1.5.0":"جسر Freally MIDI Master.","ladder.rung.v1.6.0":"عمق القائمة ومجموعة البيانات.","ladder.rung.v1.7.0":"التصدير والتوافق.","ladder.rung.v1.8.0":"عمق سير العمل وإمكانية الوصول.","ladder.rung.v1.9.0":"التكامل مع Freally.","ladder.note":"الإصدار المكتمل مبنيّ ومُوسوم. إنه ليس تنزيلًا: لا يوجد أي منها، ولن يوجد حتى الإصدار 1.0.0.","honest.title":"الأشياء التي تضعها معظم المواقع في الأسفل","honest.notes.title":"يوزّع موسيقاك؛ ولا يكتب أي موسيقى","honest.notes.body":"كل صوت في المقطوعة المُوزَّعة يأتي من مقطعك، أو هو مؤثر انتقال يبنيه Unloop من المذبذبات والضجيج. يقرر متى يُعزف كل جزء ويؤدي عليه الحركات، لكنه لا يكتب أبدًا نوتة واحدة من موسيقى جديدة، ولا يغيّر أبدًا ملف المقطع على قرصك. أما الحشوة الإيقاعية الجديدة، أو الإيقاع الثاني لتبديل الإيقاع، فيأتيان منك.","honest.bands.title":"يُوزَّع مقطع الستيريو الواحد في ثلاثة نطاقات","honest.bands.body":"حين لا يتوفر سوى مقطع ستيريو مكتمل للعمل عليه، يحرّك Unloop نطاقاته المنخفضة والمتوسطة والمرتفعة، لذا لا تستطيع الحركة فصل السنير عن اللحن. ضع نسخة على المسار الخاص بكل جزء لتحصل على مجموعة الحركات كاملة.","honest.styles.title":"الأسماء تصف الأساليب","honest.styles.body":"تُستخدم أسماء الفنانين والمنتجين والأنواع الموسيقية لوصف الأساليب الموسيقية فقط. لا يرتبط Freally Unloop بأي فنان أو منتج أو شركة تسجيلات أو صاحب حقوق، ولا يحظى بتأييد أيٍّ منهم أو رعايته أو موافقته، ولا يعيد أبدًا إنشاء توزيع أغنية بعينها.","honest.styles.link":"اقرأ إخلاء المسؤولية كاملًا (باللغة الإنجليزية)","honest.hands.title":"لم يُجرَّب يدويًا بعد في كل DAW","honest.hands.body":"يُبنى Unloop ويُفحص ببوابات آلية على Windows وLinux وmacOS. أما اختباره يدويًا في برامج DAW حقيقية، على كل نظام، فهو مهمة الإصدار المرشّح، قبل 1.0.0.","honest.downloads.title":"لا توجد تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية في هذه الصفحة، ولا إصدار معاينة، ولا وصول مبكر. أداة توزيع تعمل نصف عمل أسوأ من أداة لم تصل بعد.","honest.network.title":"لا تتصل بالإنترنت أبدًا","honest.network.body":"لا يحتوي المكوّن الإضافي ولا التطبيق المستقل على أي شيفرة شبكة على الإطلاق، وتفشل بوابة بناء إذا أُضيفت أي شيفرة من هذا القبيل. قد يضيف إصدار لاحق فحص تحديثات يكون مطفأً ما لم تُفعّله بنفسك، ويشغّله برنامج منفصل.","site.tagline":"كل مقطع متكرر مقطوعةٌ تنتظر أن تولد.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © Mike Weaver. الاستخدام مجاني اليوم؛ وقد تُباع الإصدارات المستقبلية. ليس مفتوح المصدر.","footer.yours":"الموسيقى التي تصنعها بـ Unloop ملكك، بقدر ما كانت المقاطع التي وزّعتها مما يحق لك استخدامه، دون أي عائدات ودون اشتراط ذكر المصدر.","featuresPage.lead":"يحوّل Freally Unloop مقطعًا متكررًا من 8 مازورات إلى مقطوعة مكتملة ومُوزَّعة بأسلوب أيٍّ من 2,413 فنانًا ومنتجًا ونوعًا موسيقيًا — تُعزف فوق صوتك أنت، مباشرةً في الـ DAW الخاص بك، ثم تُسحب إلى الخارج كمسارات صوتية منفصلة أو كقالب أغنية MIDI.","featuresPage.version":"تصف هذه الصفحة الإصدار 1.0 من Freally Unloop: كل ما فيها موجود في 1.0، ولا يوجد فيها شيء مخطط لما بعد 1.0.","featuresPage.numbers.names":"فنانًا ومنتجًا ونوعًا موسيقيًا توزّع على طريقتهم","featuresPage.numbers.artists":"فنانين","featuresPage.numbers.producers":"منتجًا","featuresPage.numbers.genres":"أنواع موسيقية","featuresPage.numbers.flagships":"أسلوب رائد، حتى أدق حركاته المميزة","featuresPage.numbers.lanes":"مسار أتمتة لكل جزء","featuresPage.numbers.formats":"صيغ ملفات للتصدير: WAV وAIFF وFLAC وMP3 وMIDI","featuresPage.numbers.latency":"عيّنات تأخير مُضاف","featuresPage.numbers.systems":"أنظمة تشغيل: Windows وmacOS وLinux","featuresPage.numbers.languages":"لغة","featuresPage.numbers.ai":"نماذج ذكاء اصطناعي","featuresPage.numbers.price":"السعر اليوم","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"كل ما يفعله Unloop اليوم مجاني للجميع: لا مستوى مدفوع، ولا اشتراك، ولا حساب، ولا مفتاح ترخيص، ولا إعلانات، ولا نسخة تجريبية تنتهي مدتها. التوزيعات والصوت والمسارات المنفصلة وملفات MIDI التي تصنعها به ملكك، بقدر ما كانت المقاطع التي وزّعتها مما يحق لك استخدامه.","featuresPage.cards.title":"ما يفعله الإصدار 1.0","featuresPage.cards.search.title":"ابحث عن اسم، لا عن نوع موسيقي","featuresPage.cards.search.body":"2,413 فنانًا ومنتجًا ونوعًا موسيقيًا في بحث واحد، حتى عبر الأسماء البديلة والأخطاء الإملائية. وقبل أن تضغط أي شيء، تخبرك بطاقة بما يفعله ذلك الاسم: أشكال أغانيه، وطرق توزيعه، وأطوال أقسامه، وحركاته المميزة.","featuresPage.cards.modes.title":"لا قالب واحدًا لكل نوع","featuresPage.cards.modes.body":"يُوزَّع النوع الموسيقي بعدة طرق — نسخة الإذاعة، ونسخة المكستيب، ونسخة النادي، والتبديل المفاجئ، والنمط البسيط — إلا إذا كانت له طريقة واحدة فعلًا، وعندها تشرح بطاقته السبب. ويضيف الفنانون والمنتجون طرقهم الخاصة، وكل ضغطة بذرة جديدة يمكنك الاحتفاظ بها ولصقها لتستعيد التوزيع نفسه.","featuresPage.cards.live.title":"المقطوعة كاملة، تُعزف مباشرةً","featuresPage.cards.live.body":"اضغط تشغيل فيعزف Unloop المقطوعة فوق صوتك أنت، بتزامن مع مشروعك: المقدمات، واللوازم، والانقطاعات، وقطع 808، ومسح المرشح، والتصاعدات المتقطعة، وإيقاف الشريط، ونصف الإيقاع، وتبديلات الإيقاع. لا حركة تُحدث طقطقة، ولا حركة تضيف تأخيرًا.","featuresPage.cards.pattern.title":"حتى على مقطع متكرر لا يتقدّم أبدًا","featuresPage.cards.pattern.body":"يكرّر وضع الأنماط في FL Studio وعرض الجلسة في Ableton المقطع دون تحريك موضع الأغنية. يعدّ Unloop الدورات بنفسه، فتُعزف المقطوعة كاملة رغم ذلك فوق المازورات الـ 8 وهي تدور.","featuresPage.cards.parts.title":"مقطع واحد، أو كل جزء","featuresPage.cards.parts.body":"يكفي مقطع ستيريو واحد: يوزّعه Unloop في نطاقات منخفضة ومتوسطة ومرتفعة. أو ضع نسخة على مسار كل جزء، فتقودها إحداها جميعًا كمقطوعة واحدة، مع وحدة تحكم كاملة من المُخفِتات والمصابيح.","featuresPage.cards.timeline.title":"الخط الزمني بين يديك","featuresPage.cards.timeline.body":"انقل كل مقطع وانسخه وقسّمه وغيّر حجمه وطبّق عليه التلاشي بمقابض تلاشٍ ثلاثية؛ وحرّك مُخفِتات المقاطع والأجزاء والمُخفِت الرئيسي؛ وارسم الأتمتة على 12 مسارًا لكل جزء؛ وأعد ترتيب الأقسام؛ واقفل ما يعجبك وأعد سحب الباقي. تراجع بلا حدود، وحفظ تلقائي يصمد أمام الانهيار.","featuresPage.cards.take.title":"استمع إليه، ثم خذه","featuresPage.cards.take.body":"عاين التوزيع داخل Unloop بينما الـ DAW متوقف. صيّره بصيغة WAV أو AIFF أو FLAC أو MP3، مزيجًا أو مسارًا منفصلًا لكل جزء، واسحب الأغنية أو جزءًا واحدًا أو قسمًا واحدًا مباشرةً إلى مساراتك. ويُكتب إيصال بجانب كل ملف.","featuresPage.cards.midi.title":"صوت أو MIDI، بمفتاح واحد","featuresPage.cards.midi.body":"بدّل إلى MIDI ليصبح التوزيع نفسه قالب أغنية MIDI متعدد المسارات، مقروءًا من نوتات مقطعك أنت، مع علامات للأقسام. ويمنح طبيب قوة العزف كل جزء النوع المناسب من قوة العزف: نبرات ونقرات خافتة على الطبول، و808 ثابتًا، وأوتارًا متساوية القوة.","featuresPage.cards.shelf.title":"مقطع واحد، توزيعات كثيرة","featuresPage.cards.shelf.body":"يُحفظ كل مقطع مرة واحدة، كمشروع مستقل، مع رفّ من التوزيعات المُسمّاة: بدّل بينها عند المازورة التالية، وقارن أي اثنين منها، وانقل أحدها إلى مقطع آخر كملف. وتضم مكتبة المقاطع كل مقاطعك، جاهزة للاستماع.","featuresPage.cards.standalone.title":"تطبيق مستقل وتطبيق ويب","featuresPage.cards.standalone.body":"أفلِت حتى ثمانية مسارات منفصلة أو ملفات MIDI ووزّعها دون DAW. ومن دون DAW يتبعه، يقترح Unloop إيقاع الفنان ويمكنه تمديد مقطعك ليطابقه؛ ويكتشف طبيب المقاطع طقطقات نقاط الوصل، والقصّ الرقمي، والإيقاع الذي لا يستقيم حسابه.","featuresPage.cards.redream.title":"إعادة التخيّل وطبيب التوزيع","featuresPage.cards.redream.body":"تمنحك إعادة التخيّل ثلاث رؤى جديدة للتوزيع الذي لديك، مع الحفاظ على شكله. أضف مؤثرات صاعدة وضربات مُركَّبة، وتوقيعك الخاص كمنتج، وتبديلات الإيقاع، ثم دع طبيب التوزيع يشير إلى لازمة متأخرة أو قسم لا يتغيّر أبدًا، مع حلٍّ له.","featuresPage.cards.offline.title":"بلا اتصال، خاص، بلا ذكاء اصطناعي","featuresPage.cards.offline.body":"لا حساب، ولا قياس عن بُعد، ولا نموذج: مُخطِّط قائم على القواعد ومعالجة إشارة كلاسيكية، تتحقق منهما بوابة بناء. لا يتصل المكوّن الإضافي ولا التطبيق المستقل بالإنترنت أبدًا؛ والاستثناء الوحيد فحص للتحديثات يبقى مُعطَّلًا ما لم تُفعّله، ويشغّله برنامج منفصل.","featuresPage.compare.title":"جنبًا إلى جنب مع الأدوات التجارية","featuresPage.compare.intro":"Freally Unloop 1.0 إلى جانب خمسة منتجات تُباع اليوم توزّع مقطعًا متكررًا أو تنوّع عليه أو تكتب أغاني كاملة: ArrangerKing (مكوّن إضافي للتوزيع)، وLoopmix (مكوّن إضافي لإعادة مزج المقاطع)، وSongen (تطبيق لصنع الإيقاعات)، وSuno وSOUNDRAW (مولّدا أغانٍ بالذكاء الاصطناعي). كل خانة لمنتج آخر مأخوذة من صفحات صانعه نفسه، وقد جرى التحقق منها في 1 و2 أكتوبر 2026، والأسعار بالدولار الأمريكي قبل الضريبة، كما كانت معروضة في 2 أكتوبر 2026.","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.price":"السعر (USD، أكتوبر 2026)","featuresPage.compare.freeToday":"مجاني اليوم","featuresPage.compare.price.songen":"مستوى مجاني؛ Premium بسعر $89.99 سنويًا","featuresPage.compare.price.suno":"مستوى مجاني؛ Pro بسعر $10 وPremier بسعر $30 شهريًا","featuresPage.compare.price.soundraw":"من $16.99 شهريًا؛ المسارات المنفصلة من $35.99","featuresPage.compare.row.yourLoop":"يحوّل مقطعك أنت إلى أغنية كاملة نيابةً عنك، دون كتابة أي موسيقى جديدة","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.legend.partly":"جزئيًا","featuresPage.compare.note.setMutes":"تضبط كل كتم بنفسك","featuresPage.compare.note.variations":"تنويعات على المقطع","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.note.writesOwn":"يكتب موسيقاه الخاصة","featuresPage.compare.note.writesNew":"يكتب موسيقى جديدة","featuresPage.compare.row.styleOf":"يوزّع بأسلوب فنان أو منتج تسمّيه","featuresPage.compare.note.names":"2,340 منهم","featuresPage.compare.note.genreTemplates":"قوالب أنواع موسيقية","featuresPage.compare.note.genres":"أنواع موسيقية","featuresPage.compare.note.nameStops":"ذكر اسم قد يوقف الأغنية","featuresPage.compare.note.genresMoods":"أنواع موسيقية وأمزجة","featuresPage.compare.row.moves":"حركات تُعزف على صوتك أنت: قطع 808، والتصاعدات المتقطعة، وإيقاف الشريط","featuresPage.compare.note.mutesOnly":"الكتم فقط","featuresPage.compare.note.gateReverse":"بوابة، عكس، طبقة","featuresPage.compare.row.edit":"كل مقطع وتلاشٍ ومُخفِت ومسار أتمتة قابل للتحرير","featuresPage.compare.note.partsMutes":"الأجزاء والكتم","featuresPage.compare.note.arrangementNotes":"التوزيع والنوتات","featuresPage.compare.note.premierStudio":"Premier، في Studio","featuresPage.compare.note.muteSolo":"كتم، عزف منفرد، شدة","featuresPage.compare.row.stems":"تصدير مسارات صوتية منفصلة","featuresPage.compare.note.ofLoop":"لمقطع متكرر واحد","featuresPage.compare.note.paidPlans":"الخطط المدفوعة","featuresPage.compare.note.artistPro":"Artist Pro وما فوق","featuresPage.compare.row.midi":"الأغنية كملف MIDI","featuresPage.compare.note.fromYourLoop":"من مقطعك أنت","featuresPage.compare.note.guideTracks":"مسارات إرشادية فقط","featuresPage.compare.row.plugin":"مكوّن إضافي في الـ DAW الخاص بك","featuresPage.compare.row.systems":"أصلي على Windows وmacOS وLinux","featuresPage.compare.note.wine":"Linux عبر Wine فقط","featuresPage.compare.note.browser":"في المتصفح","featuresPage.compare.row.offline":"يعمل بلا اتصال","featuresPage.compare.legend.unknown":"لم يُتحقَّق منه","featuresPage.compare.row.account":"بلا حساب ولا قياس عن بُعد","featuresPage.compare.note.usageData":"يرسل بيانات الاستخدام","featuresPage.compare.note.account":"يتطلّب حسابًا","featuresPage.compare.row.noAi":"لا ذكاء اصطناعي في أي مكان","featuresPage.compare.note.buildGate":"تتحقق منه بوابة بناء","featuresPage.compare.note.ownAi":"ذكاؤه الاصطناعي الخاص","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"باختصار: Unloop وحده يحوّل مقطعك أنت إلى مقطوعة كاملة نيابةً عنك، بأسلوب فنان أو منتج تسمّيه، مع حركات تُعزف على صوتك أنت. وهو الوحيد الأصلي على Linux إلى جانب Windows وmacOS، والوحيد الذي يعمل بلا اتصال، بلا حساب ولا قياس عن بُعد ولا ذكاء اصطناعي.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"أين يتفوّقون: يكتب Suno وSOUNDRAW وSongen موسيقى جديدة لك — وهو ما لا يفعله Unloop أبدًا، عن قصد. ويقطّع Loopmix محتوى المقطع ويعيد ترتيبه بدلًا من توزيعه في أغنية، وهو أيضًا مكوّن إضافي بصيغة AAX لـ Pro Tools، وهو ما ليس عليه Unloop 1.0.","featuresPage.compare.asOf":"عمود Unloop هو الإصدار 1.0، الذي لم يصدر بعد، وسعره هو سعر اليوم: Unloop مجاني اليوم، وقد تُباع الإصدارات المستقبلية. والمنتجات الأخرى تتغيّر أيضًا؛ هذا الجدول محدَّث حتى 2 أكتوبر 2026. أسماء المنتجات علامات تجارية لأصحابها، ولا يرتبط Freally Unloop بأيٍّ منها.","featuresPage.why.title":"لماذا بُني على هذا النحو","featuresPage.why.sound.title":"صوتك، مُوزَّعًا — لا مُستبدَلًا أبدًا","featuresPage.why.sound.body":"كل صوت في المقطوعة المُوزَّعة يأتي من مقطعك، أو هو مؤثر انتقال يبنيه Unloop من المذبذبات والضجيج. لا يكتب أبدًا نوتة واحدة من موسيقى جديدة في أغنيتك، ولا يغيّر أبدًا ملف المقطع على قرصك.","featuresPage.why.rules.title":"قواعد يمكنك قراءتها","featuresPage.why.rules.body":"يقرأ مُخطِّطٌ بيانات توزيع مدروسة لكل فنان ومنتج ونوع موسيقي، ويقرّر كل قسم وكل حركة قبل أن يُعزف أي صوت. المقطع نفسه والاسم نفسه والنمط نفسه والبذرة نفسها تعطي التوزيع نفسه اليوم وبعد خمس سنوات — فالبذرة التي ترسلها إلى شريكك في العمل تُسمعه بالضبط ما سمعته.","featuresPage.why.views.title":"عرضان، وحقيقة واحدة","featuresPage.why.views.body":"يُستمدّ الصوت وقالب أغنية MIDI من الخطة نفسها، ويصل كل تعديل إلى كليهما. وحين لا يستطيع MIDI التعبير عمّا فعلته حركة ما — كغطسة الطبقة في إيقاف الشريط — تُوسَم الحركة بأنها صوتية فقط بدلًا من إسقاطها بصمت.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا حساب، ولا قياس عن بُعد، ولا سحابة. لا تغادر مقاطعك ومقطوعاتك حاسوبك أبدًا، وتفشل بوابة البناء إذا وصلت شيفرة شبكة إلى المكوّن الإضافي أو التطبيق المستقل. يُحمَّل تطبيق الويب مرة واحدة، ثم يعمل بلا اتصال ولا يرفع أي شيء.","featuresPage.why.tempo.title":"يتبع الـ DAW الخاص بك","featuresPage.why.tempo.body":"يعزف المكوّن الإضافي دائمًا بإيقاع مشروعك ولا يغيّره أبدًا. وحين يعمل الفنان أو المنتج الذي اخترته بإيقاع آخر، يقترحه Unloop، ويعدّ نصف الإيقاع وضعفه تطابقًا. وفي التطبيق المستقل وتطبيق الويب، يمكنه تمديد مقطعك إلى إيقاعهم.","featuresPage.why.styles.title":"أساليب، لا أغانٍ أبدًا","featuresPage.why.styles.body":"الاسم يصف كيف يوزّع شخص ما، ولا شيء أكثر. لا يعيد Unloop أبدًا إنشاء توزيع أغنية بعينها، ولا يضع الأسماء في أسماء ملفاتك ما لم تضعها أنت.","featuresPage.coming.title":"ما لا يزال قادمًا","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة ميزات تخفي ثغراتها لا تستحق القراءة. تصف هذه الصفحة الإصدار 1.0، ويُبنى Unloop درجةً درجة، لذا لم يُبنَ كل ما فيها بعد. وكل درجة على الطريق إلى 1.0 موسومة بحالتها.","featuresPage.limits.title":"ما لا يفعله 1.0","featuresPage.limits.newMusic":"لا يكتب موسيقى جديدة. الحشوة الإيقاعية الجديدة، أو النمط الثاني لتبديل الإيقاع، يأتيان منك: يوزّع Unloop ما في مقطعك ولا يضيف إلا مؤثرات الانتقال التي يُركّبها بنفسه.","featuresPage.limits.songs":"لا يعيد إنشاء توزيع أغنية مشهورة، ولن يفعل ذلك أبدًا.","featuresPage.limits.bands":"يُوزَّع مقطع الستيريو الواحد في ثلاثة نطاقات، لذا لا تستطيع الحركة فصل السنير عن اللحن. امنح كل جزء مساره الخاص لتحصل على مجموعة الحركات كاملة؛ وعند التصيير، يساعد الفصل بين الإيقاعي والتوافقي، ويوضّح Unloop أنه تقريبي.","featuresPage.limits.midi":"يصرّح تحويله من الصوت إلى MIDI بما لا يستطيع فعله: لا لحن مضاد من الصوت، والأوتار تُكتب ببساطة، والخط الغنائي يُترك بدلًا من تخمينه.","featuresPage.limits.daw":"إنه أداة توزيع، لا DAW: لا تسجيل، ولا استضافة للمكوّنات الإضافية، ولا مازج سوى مُخفِتات الأجزاء والمُخفِت الرئيسي.","featuresPage.limits.aax":"ليس مكوّنًا إضافيًا لـ Pro Tools (AAX).","featuresPage.coming.downloads":"لا توجد تنزيلات قبل الإصدار 1.0، ولا يوجد أي منها في هذه الصفحة.","docs.intro":"يصف هذا الدليل الإصدار 0.6.0، وهو الإصدار المبني اليوم. وحيثما يصل شيء مذكور في صفحة الميزات في إصدار لاحق، يذكر الدليل أيّ إصدار هو.","docs.start.title":"البدء","docs.agreement.title":"اتفاقية الترخيص","docs.window.title":"النافذة","docs.name.title":"اختيار اسم","docs.generate.title":"الإنشاء والأنماط والبذور","docs.tempo.title":"الإيقاع والساعة","docs.parts.title":"مقطع واحد، أو كل جزء","docs.capture.title":"الالتقاط والمعاينة","docs.print.title":"التصيير والسحب والإيصالات","docs.projects.title":"مشاريع المقاطع ومكتبة المقاطع","docs.timeline.title":"تحرير الخط الزمني","docs.fades.title":"التلاشي والمُخفِتات","docs.automation.title":"الأتمتة","docs.sections.title":"الأقسام","docs.reroll.title":"القفل وإعادة السحب والحركات يدويًا","docs.history.title":"التراجع والإعادة والحفظ التلقائي","docs.shelf.title":"توزيعات كثيرة على مقطع واحد","docs.keys.title":"اختصارات لوحة المفاتيح","docs.privacy.title":"الخصوصية والشبكة","docs.limits.title":"قيود معروفة","docs.start.p1":"يعمل Freally Unloop داخل الـ DAW الخاص بك كمكوّن إضافي بصيغة CLAP أو VST3، أو بصيغة AU على macOS، ويعمل وحده كتطبيق مستقل. ضعه على المسار الذي يعزف مقطعك: إلى أن تضغط «إنشاء»، يمرّر صوت المسار تمامًا كما يصل، لذا من الآمن تركه في مكانه.","docs.start.p2":"بُني الإصدار 0.6.0 ليُستخدم في DAW، مع الصوت. يصل MIDI في الإصدار 0.7.0؛ أما توزيع المسارات المنفصلة المُفلَتة في التطبيق المستقل، وتطبيق الويب، فيصلان في الإصدار 0.8.0.","docs.start.p3":"لا توجد تنزيلات قبل الإصدار 1.0.0، والشيفرة المصدرية خاصة.","docs.agreement.p1":"في المرة الأولى التي يُفتح فيها Unloop، يعرض اتفاقية ترخيص المستخدم النهائي، وهي مكتوبة باللغة الإنجليزية. اقرأها حتى النهاية ليصبح زر «موافق» متاحًا.","docs.agreement.p2":"إذا رفضت، يتوقف Unloop مؤقتًا: لا يُوزَّع أي شيء، ويظل صوتك يمر دون تغيير. اختر «اقرأها مرة أخرى» متى كنت جاهزًا. تُحفظ إجابتك على حاسوبك، لكل نسخة من Unloop عليه.","docs.window.p1":"في الأعلى: قائمة مشروع المقطع (زر المجلد)، وقائمة «التوزيع»، والبحث، والنمط، و«تراجع» و«إعادة»؛ وفي آخر الشريط: الإيقاع، والساعة، و«الإعدادات» (الترس). في المنتصف خريطة التوزيع: أقسام المقطوعة، ومسار لكل جزء، وحركاتها. وفي الأسفل وحدة التحكم: «إنشاء»، وشريط لكل جزء، والقسم الرئيسي، والبذرة.","docs.window.p2":"تضم «الإعدادات» اللغة، والمظهر — «النظام» أو «داكن» أو «فاتح» — وقائمة اختصارات لوحة المفاتيح.","docs.name.p1":"اكتب في البحث لتجد أيًّا من 2,413 فنانًا ومنتجًا ونوعًا موسيقيًا. تجدها الأسماء البديلة والأخطاء الإملائية القريبة أيضًا، وتُطوى حروف مثل Ø وß وŁ إلى أصلها، فتجد «mo» الاسمَ MØ. وحين يكون البحث فارغًا، يعرض أسماءك الأخيرة والنماذج الرئيسية. استخدم مفاتيح الأسهم وEnter، أو انقر.","docs.name.p2":"لكل اسم بطاقة نموذج: الأنماط التي يوزّع بها وكم مرة يُسحب كلٌّ منها، وأشكال أغانيه المعتادة، وحركاته المميزة، والأجزاء التي يتحكم بها، ومصدر بياناته، ودرجة الثقة فيها. والاسم الذي لديه بيانات قليلة خاصة به يرث من نوعه الموسيقي، وتعرض البطاقة سلسلة الوراثة.","docs.generate.p1":"اضغط «إنشاء» فيخطط Unloop المقطوعة كاملة للاسم الذي اخترته: كل قسم، والأجزاء التي تُعزف فيه، وكل حركة. اختر نمطًا أولًا — «نسخة الإذاعة» أو «نسخة المكستيب» أو «نسخة النادي / DJ» أو «تبديل مفاجئ» أو «بسيط» وغيرها، بحسب الاسم — أو اتركه على «أي نمط» فيسحب Unloop نمطًا بنفسه.","docs.generate.p2":"لكل خطة بذرة، من 16 رقمًا ست عشريًا تظهر في وحدة التحكم، وكل ضغطة على «إنشاء» تسحب بذرة جديدة. المقطع نفسه والاسم نفسه والنمط نفسه والبذرة نفسها تعطي دائمًا التوزيع نفسه: انسخ بذرة لتحتفظ بتوزيع أو لترسله إلى شريكك في العمل، والصق واحدة لتستعيده.","docs.tempo.p1":"في الـ DAW، يعزف Unloop دائمًا بإيقاع مشروعك ولا يغيّره أبدًا. وتوضّح شارة الإيقاع ما إذا كان إيقاعك ضمن النطاق الذي يعمل به الاسم عادةً — مع عدّ نصف الإيقاع وضعفه تطابقًا — وإن لم يكن كذلك، فعلى أيّ إيقاع تضبط الـ DAW، مع زر لنسخه.","docs.tempo.p2":"يحتاج Unloop إلى معرفة طول مقطعك: فيسألك، ويفترض 8 مازورات حتى تحدد غير ذلك. تتبع الساعة موضع الأغنية في الـ DAW، أو تعدّ الدورات بنفسها حين لا يتحرك الموضع — كما في وضع الأنماط في FL Studio أو عرض الجلسة في Ableton Live — فتُعزف المقطوعة كاملة رغم ذلك فوق مقطع يدور. «تلقائي» يقرر نيابةً عنك؛ واختر «الأغنية» أو «مقطع متكرر» لتقرر بنفسك.","docs.parts.p1":"على مسار واحد يحمل مقطع ستيريو مكتملًا، يوزّعه Unloop في ثلاثة نطاقات — منخفض ومتوسط ومرتفع — وتوضّح الخريطة ذلك.","docs.parts.p2":"للحصول على مجموعة الحركات كاملة، ضع نسخة على مسار كل جزء وامنح كلًّا منها دورًا: الطبول، أو الجهير، أو اللحن، أو الأوتار، وهكذا. ويقترح Unloop دورًا من اسم المسار. تعزف النسخ على القناة نفسها مقطوعة واحدة معًا: الأولى تقود، وكل نسخة أخرى تتبع خطتها حتى العيّنة الواحدة ولا تعزف إلا حركات جزئها. وتعرض وحدة التحكم شريطًا لكل نسخة، بمُخفِته ومصابيحه.","docs.parts.p3":"حين يشغّل الـ DAW المكوّنات الإضافية في عمليات منفصلة، تلتقي النسخ عبر ملف مشترك على حاسوبك، لا عبر الشبكة أبدًا. وإذا كانت خطة مشروع آخر موجودة بالفعل على قناة ما، يخبرك Unloop بذلك ويعرض قناة أخرى.","docs.capture.p1":"بعد «إنشاء»، تلتقط كل نسخة دورة واحدة من مقطعها — الموسيقى الواصلة إلى مسارها، لا مخرجها هي أبدًا — ومن ثمّ تعزف المقطوعة من الذاكرة. وتوضّح شارة «مباشر / مُلتقَط» حالتها، مع «إعادة الالتقاط» و«انسَ الالتقاط». لا يمكن التقاط مقطع أطول من 64 ثانية، وإذا حدث إيقاف أو قفزة أو تغيير في الإيقاع أثناء الالتقاط، يبدأ الالتقاط من جديد عند التشغيل التالي.","docs.capture.p2":"إذا لم يعد المقطع الوارد هو المقطع الذي التُقط، تسأل الشارة: «تغيّر المقطع — إعادة الالتقاط؟» لا يُستبدل شيء أثناء التشغيل؛ وإعادة الالتقاط قرارك أنت، بضغطة منك.","docs.capture.p3":"حين يكون الـ DAW متوقفًا، تعاين أزرار التشغيل والإيقاف المؤقت والإيقاف والتكرار في القسم الرئيسي — أو مفتاح المسافة — المقطوعةَ كاملة داخل Unloop، مع كل النسخ على القناة معًا. انقر مسطرة الخريطة للقفز، أو كرّر قسمًا. اضغط تشغيل في الـ DAW فيتولّى الأمر فورًا.","docs.print.p1":"يفتح زر «تصيير» في القسم الرئيسي نافذة «التصيير والتصدير». اختر ما تريد تصييره — المزيج، أو المسارات المنفصلة، أو أيًّا من الأجزاء، أو قسمًا، أو المقطوعة كاملة — والصيغة: WAV (16 بت أو 24 بت أو 32 بت عائم) أو AIFF أو FLAC أو MP3، بمعدل العينات الملتقَط أو بمعدل تختاره. يُصيَّر عبر الشيفرة نفسها التي تعزف مباشرةً، فيكون الملف هو ما سمعته بالضبط. و«إلغاء» لا يترك أي أثر.","docs.print.p2":"يمكنك إضافة الديثر عند خفض عمق البت، ووضع محدِّد أمان عند −1 dBTP على المزيج، وكتابة إيصالات. تأتي أسماء الملفات من قالب يمكنك تحريره، وافتراضيًا لا يحمل أي اسم ملف اسمَ فنان أو منتج. وعند انتهاء التصدير، يعرض مقياس التصيير ذروة المزيج وذروته الحقيقية وجهارته.","docs.print.p3":"لتجاوز مربع الحوار، استخدم حامل السحب: اسحب المزيج، أو المسارات المنفصلة، أو جزءًا واحدًا، أو قسمًا واحدًا مباشرةً إلى مساراتك. تُصيَّر الملفات قبل بدء السحب، بصيغة WAV بدقة 24 بت افتراضيًا.","docs.print.p4":"يُكتب إيصال، وهو ملف .unloop-receipt.json صغير، بجانب كل تصدير وكل سحب. يحمل الإصدارات، والاسم والنمط والبذرة، والبصمات اللازمة لصنع المقطوعة نفسها مرة أخرى. الإيصالات مفعّلة افتراضيًا؛ ويمكنك إيقافها في مربع الحوار.","docs.projects.p1":"يحفظ الأمر «احفظ مشروع المقطع…» في قائمة مشروع المقطع (زر المجلد) المقطعَ — أجزاءه بصيغة FLAC بدقة 24 بت — مع كل توزيع فوقه، في ملف .unloop واحد. ويعيده «افتح مشروع مقطع…» كما كان تمامًا. لا يستبدل الحفظ أي ملف أبدًا: الاسم المأخوذ يُضاف إليه (2).","docs.projects.p2":"تعرض «مكتبة المقاطع»، في القائمة نفسها، كل مشروع .unloop وكل ملف WAV وAIFF وFLAC وMP3 وMIDI في المجلدات التي تضيفها، مع مازوراته وإيقاعه ووسومه وعدد مرات توزيعه. ابحث فيها وصفِّها؛ وانقر مقطعًا لتسمعه داخل Unloop (تتنقل مفاتيح الأسهم في القائمة، وEsc يوقف)، ثم اضغط «وزّع» حين يكون مقطعًا واحدًا تمامًا. ولا تفعل المكتبة سوى قراءة مجلداتك. تُدرج مقاطع MIDI الآن، وتصبح قابلة للتوزيع في الإصدار 0.7.0.","docs.projects.p3":"يقتطع «اصنع مقطعًا من ملف أطول…» مقطعًا من تسجيل أطول: اختر مازورة البداية، وطولًا من 1 أو 2 أو 4 أو 8 أو 16 مازورة، والإيقاع، واستمع إلى الجزء المقتطع وهو يتكرر، ثم اضغط «وزّع» لتوزيعه كمشروع مقطع جديد. ولا يتغيّر الملف نفسه أبدًا.","docs.projects.p4":"تعرض «المشاريع الأخيرة» ما فتحته أو حفظته، الأحدث أولًا. والمشروع الذي نُقل يظهر على أنه مفقود، و«أزل من القائمة» يزيل السطر — لا الملف أبدًا.","docs.timeline.p1":"كل مقطع على الخريطة قابل لتحريرك. انقر لتحديده، وانقر مع Shift أو اسحب مستطيل تحديد لتحديد المزيد، أو اضغط Ctrl/Cmd+A لتحديدها كلها. اسحب مقطعًا لنقله وفق خطوة الالتقاط (أمسك Alt لنقله بحرية)، واسحب إحدى حافتيه لتغيير طوله — فتتكرر الحلقة بعد طولها — واسحب داخله مع Alt لإزاحة محتواه. ويقسّم S عند مؤشر التحرير.","docs.timeline.p2":"تضم قائمة المقطع — بالنقر بزر الفأرة الأيمن، أو Shift+F10، أو مفتاح القائمة — «قص» و«نسخ» و«لصق» و«استنساخ بعده» و«تكرار في المكان» و«حذف» و«تقسيم عند المؤشر» و«عكس» و«قفل» و«إعادة إلى الخطة» و«اللون» و«إعادة تسمية». والمقطع الذي يُلصق في مسار لا يمكن لجزئه أن يوضع فيه، تُعرض عليه المسارات التي يمكنه الذهاب إليها.","docs.timeline.p3":"اضبط الالتقاط على المازورة، أو النبضة، أو النوتة الثُمنية، أو النوتة السادسة عشرية، أو ثلاثياتها، أو لا شيء؛ وكبّر وصغّر، أو اعرض المقطوعة كاملة. وحيث تلتقي المقاطع، يمزجها Unloop بتلاشٍ متقاطع على مدى 3 ms، ومع إيقاف الالتقاط تستقر الحافة على أقرب نقطة عبور صفري في الحلقة، فلا يُحدث أي تعديل طقطقة.","docs.fades.p1":"لكل طرف من طرفي المقطع ثلاثة مقابض تلاشٍ، كما في عرض توزيع الأغنية في Freally MIDI Master: الطول على الحافة العليا للمقطع، والمنحنى على التلاشي نفسه. ولا تتقاطع أبدًا، أيًّا كان طول المقطع.","docs.fades.p2":"اسحب مقبض مستوى المقطع من −∞ إلى +6 dB — أمسك Shift لخطوات دقيقة، وانقر نقرًا مزدوجًا للعودة إلى 0 dB. وفي وحدة التحكم مُخفِت لكل جزء ومُخفِت رئيسي. يُسمع كل تحريك أثناء السحب، ويصبح خطوة تراجع واحدة عند الإفلات.","docs.automation.p1":"افتح «الأتمتة»، واختر جزءًا وما سيتغيّر، ثم أضف مسارًا وارسم عليه. لكل جزء مسارات لمستوى الصوت، والتوزيع الستيريو، والعرض، وتردد قطع التمرير المنخفض والتمرير العالي، والرنين، وإرسال الصدى والتأخير، والتشبّع، وتقليص البتات، وعمق البوابة، وطبقة الصوت؛ أما القناة الرئيسية فلها مستوى الصوت ومرشح تمرير منخفض.","docs.automation.p2":"ارسم نقاطًا، أو حدّدها وانقلها؛ واثنِ الخط بين نقطتين؛ واختم شكلًا فوق نطاق — منحدرًا، أو منحنى S، أو موجة جيبية أو مثلثة أو مربعة أو سن منشار، أو خطوات عشوائية — وانسخ نطاقًا والصقه. ويمكن تحرير مسح الحركة نفسها أو غطستها على المسار الذي تُعزف عليه. تُقرأ الأتمتة عيّنةً بعيّنة، في العزف المباشر وفي التصيير على حدٍّ سواء.","docs.sections.p1":"افتح قائمة القسم من ترويسته، أو اضغط M، لإعادة تسميته، أو تغيير نوعه أو طوله، أو نقله إلى وقت أبكر أو لاحق، أو إدراج قسم جديد قبله أو بعده، أو إزالته، أو قفله. ويمكنك أيضًا سحب قسم لإعادة ترتيبه: كل ما فيه ينتقل معه.","docs.reroll.p1":"اقفل قسمًا أو مقطعًا يعجبك، فتسحب «إعادة السحب» الباقي من جديد. لا تمسّ أبدًا قسمًا مقفلًا أو مقطعًا حرّرته، ولا تحرّك أبدًا ما يجاوره. ثم تعرض «ما الذي تغيّر» كل جزء وحركة غيّرتها، قسمًا قسمًا.","docs.reroll.p2":"يفتح «إضافة حركة» لوحة بكل الحركات، تتصدّرها حركات هذا التوزيع: ضع واحدة على شريط الحركات، ثم اسحبها أو مدّدها أو احذفها. حدّد حركة لتفتح لوحة خصائصها — بدايتها وطولها وأجزاءها وإعداداتها الخاصة، مثل نطاق المرشح أو درجات التقطيع — واضغط «استماع» لسماعها بينما تُعزف المعاينة.","docs.history.p1":"كل تغيير في عرض توزيع الأغنية خطوة واحدة من تراجع وإعادة بلا حدود. استخدم زرَّي «تراجع» و«إعادة» في الأعلى، وكلٌّ منهما يسمّي خطوته، أو اضغط Ctrl/Cmd+Z وCtrl/Cmd+Shift+Z (أو Ctrl+Y). ويُحفظ السجل مع مشروع الـ DAW.","docs.history.p2":"ويُكتب كل تغيير أيضًا على حاسوبك فورًا، فإذا أُغلق الـ DAW قبل أن تحفظ، يُعاد فتح المشروع على آخر تغيير أجريته ويخبرك بذلك. وإذا كان ذلك التغيير يخص في الواقع نسخة أخرى — مشروعًا أقدم أُعيد فتحه بعد «حفظ باسم» — فاختر «الاحتفاظ بالنسخة المحفوظة».","docs.shelf.p1":"تضم قائمة «التوزيع» كل توزيعات المقطع المفتوح لديك: «توزيع جديد»، و«تكرار»، و«إعادة تسمية»، و«حذف»، و«تبديل» — عند المازورة التالية أثناء التشغيل، وفورًا عند التوقف — و«مقارنة»، وهي مقارنة A/B بين أي توزيعين. ويحتفظ كل توزيع بأربع لقطات، من A إلى D: انقر واحدة لاسترجاعها، أو انقر مع Shift لحفظ التوزيع فيها.","docs.shelf.p2":"يكتب «تصدير التوزيع…» توزيعًا واحدًا في ملف .unarr، دون المقطع المتكرر الخاص به. ويضع «استيراد توزيع…» توزيعًا فوق المقطع المتكرر المفتوح لديك، فيجد كل قسم ومقطع وحركة ومسار بحسب ماهيته، ويعرض كل ما لم يجد له مكانًا.","docs.keys.intro":"كل تعديل في عرض توزيع الأغنية يعمل دون فأرة. في Unloop، اضغط <kbd>?</kbd> لعرض هذه القائمة؛ وعلى Mac، يعني <kbd>Ctrl/⌘</kbd> المفتاح <kbd>⌘</kbd>.","shortcutScope.everywhere":"في كل مكان","shortcut.undo":"تراجع","shortcut.redo":"إعادة","docs.keys.or":"أو","shortcut.sheet":"عرض قائمة الاختصارات هذه","shortcut.preview":"شغّل المعاينة أو أوقفها مؤقتًا بينما الـ DAW متوقف","shortcut.closeDialog":"أغلق مربع حوار أو بطاقة أو لوحة","shortcutScope.timeline":"عرض توزيع الأغنية","shortcut.nextClip":"تحديد المقطع التالي","shortcut.previousClip":"تحديد المقطع السابق","shortcut.clipAbove":"تحديد المقطع في المسار الأعلى","shortcut.clipBelow":"تحديد المقطع في المسار الأدنى","shortcut.selectAll":"تحديد كل المقاطع","shortcut.deselect":"إلغاء التحديد، أو إلغاء السحب الجاري","shortcut.moveEarlier":"نقل المقاطع المحددة إلى وقت أبكر بخطوة الالتقاط","shortcut.moveLater":"نقل المقاطع المحددة إلى وقت لاحق بخطوة الالتقاط","shortcut.moveUp":"نقل المقاطع المحددة إلى المسار الأعلى","shortcut.moveDown":"نقل المقاطع المحددة إلى المسار الأدنى","shortcut.endEarlier":"تقصير المقطع من نهايته","shortcut.endLater":"إطالة المقطع من نهايته","shortcut.startEarlier":"إطالة المقطع من بدايته","shortcut.startLater":"تقصير المقطع من بدايته","shortcut.gainUp":"رفع مستوى المقاطع","shortcut.gainDown":"خفض مستوى المقاطع","shortcut.cursorEarlier":"تحريك مؤشر التحرير إلى وقت أبكر","shortcut.cursorLater":"تحريك مؤشر التحرير إلى وقت لاحق","shortcut.split":"تقسيم عند مؤشر التحرير","shortcut.fades":"الإمساك بمقابض تلاشي المقطع","shortcut.reverse":"عكس المقاطع المحددة","shortcut.lock":"قفل المقاطع المحددة أو فتح قفلها","shortcut.copy":"نسخ المقاطع المحددة","shortcut.cut":"قص المقاطع المحددة","shortcut.paste":"لصق عند مؤشر التحرير","shortcut.clone":"استنساخ بعد التحديد","shortcut.duplicate":"تكرار في المكان","shortcut.delete":"حذف المقاطع المحددة، أو الحركة المختارة","shortcut.clipMenu":"فتح قائمة المقطع","shortcut.sectionMenu":"فتح قائمة القسم","shortcutScope.fades":"أثناء الإمساك بمقابض التلاشي","shortcut.fadeLonger":"إطالة التلاشي بخطوة الالتقاط","shortcut.fadeShorter":"تقصير التلاشي بخطوة الالتقاط","shortcut.fadeCurveUp":"ثني منحنى التلاشي إلى الأعلى","shortcut.fadeCurveDown":"ثني منحنى التلاشي إلى الأسفل","shortcut.fadeOtherSide":"الانتقال إلى التلاشي الآخر","shortcut.fadeDone":"إفلات مقابض التلاشي","shortcutScope.fader":"على مُخفِت","shortcut.faderUp":"رفع المُخفِت خطوة واحدة","shortcut.faderDown":"خفض المُخفِت خطوة واحدة","shortcut.faderFineUp":"رفع المُخفِت خطوة دقيقة","shortcut.faderFineDown":"خفض المُخفِت خطوة دقيقة","shortcut.faderBigUp":"رفع المُخفِت ست خطوات","shortcut.faderBigDown":"خفض المُخفِت ست خطوات","shortcut.faderTop":"رفع المُخفِت إلى أقصاه","shortcut.faderOff":"إغلاق المُخفِت تمامًا","shortcutScope.lane":"على مسار أتمتة","shortcut.pointsDelete":"حذف النقاط المختارة","shortcut.pointsCancel":"إلغاء السحب الجاري","shortcutScope.search":"في البحث","shortcut.searchNext":"النتيجة التالية","shortcut.searchPrevious":"النتيجة السابقة","shortcut.searchPick":"اختيار النتيجة","shortcut.searchClose":"إغلاق النتائج","shortcutScope.menu":"في قائمة","shortcut.menuNext":"العنصر التالي","shortcut.menuPrevious":"العنصر السابق","shortcut.menuClose":"إغلاق القائمة","docs.privacy.p1":"لا يتطلب Unloop أي حساب ولا يحتوي على قياس عن بُعد، ولا يحتوي المكوّن الإضافي ولا التطبيق المستقل على أي شيفرة شبكة على الإطلاق. لا تغادر مقاطعك ومشاريعك ومقطوعاتك حاسوبك أبدًا، ويُرفض المقطع أو المشروع أو مجلد التصدير الموجود على محرك أقراص شبكي قبل أن يُلمس أي شيء عليه.","docs.privacy.p2":"يحتفظ بملفاته الخاصة في مجلد بيانات التطبيقات (%APPDATA%\\Freally Unloop على Windows): إجابتك على الترخيص، وتفضيلاتك، و«المشاريع الأخيرة»، وفهرس مكتبة المقاطع، وذاكرة الالتقاط المؤقتة (2 GB كحد أقصى)، والملفات التي تلتقي النسخ عبرها. لا يكتب أبدًا في مجلدات مقاطعك؛ وتذهب الصادرات والمشاريع إلى حيث تختار.","docs.privacy.p3":"لا يحتوي على أي نوع من الذكاء الاصطناعي: يُخطَّط كل توزيع بقواعد حتمية تعمل على بيانات توزيع مدروسة، ويُعزف بمعالجة إشارة كلاسيكية، وتفشل بوابة بناء إذا أُضيفت يومًا أي مكتبة للتعلّم الآلي.","docs.limits.midi":"يصل MIDI — قالب الأغنية ومقاطع MIDI وطبيب قوة العزف — في الإصدار 0.7.0. ولا يُعرف سلّم المقطع حتى ذلك الحين، لذا تُغفل أسماء الملفات الافتراضية السلّم.","docs.limits.picture":"لا يعرض السحب بعدُ صورةً لما تسحبه.","docs.limits.throw":"تُقطع رمية الصدى أو التأخير في المازورة الأخيرة عند خط المازورة الأخير للمقطوعة؛ ولا يستمر رنين التصيير بعده.","docs.limits.display":"على شاشة ثانية بمقياس عرض مختلف، يحدّد المحرّر حجمه وفق الشاشة الرئيسية.","docs.limits.hands":"لم يُختبر Unloop يدويًا بعد في كل DAW وعلى كل نظام. تلك مهمة الإصدار المرشّح، قبل 1.0.0.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.6.0 منجز · v0.6.5 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Unloop مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.ladder.later":"لاحقًا","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">ثمانية تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Unloop، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.footer.home":"Freally Products","kit.status.devVersion":"قيد التطوير · v0.6.0","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.numbers.lead":"كل رقم محسوب من التطبيق نفسه. لا شيء مُقدَّر، ولا شيء مُقرَّب إلى الأعلى.","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.later":"بعد ذلك، ولم يُجدوَل بعد","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Unloop، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","changelog.c4b898d0a012":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">T: الخط الزمني</span>","changelog.0a8e4d670c30":"التوزيع بين يديك لتحرّره، كل قطعة منه، وكل مخرج يسمع ما حرّرته بالضبط. انقل المقاطع وانسخها والصقها واستنسخها وغيّر حجمها وأزِح محتواها وقسّمها؛ وارسم التلاشي بمقابض MIDI Master الثلاثة؛ وحرّك مُخفِتات المقاطع والأجزاء والمُخفِت الرئيسي؛ وارسم الأتمتة؛ وأعد تشكيل الأقسام؛ واقفل ما يعجبك وأعد سحب الباقي؛ وضع الحركات يدويًا — كل تغيير خطوة تراجع واحدة، يُتراجع عنه ويُعاد بقدر ما تشاء. يضم مشروع المقطع الآن رفًّا من التوزيعات تبدّل بينها عند المازورة التالية، وينتقل التوزيع وحده كملف <code>.unarr</code>.","changelog.6b02e0d363a4":"الإضافات","changelog.b5f9159dff5a":"<strong>الخط الزمني.</strong> كل مقطع على الخريطة قابل للتحرير: التحديد (نقرة، <code>Shift</code>، مستطيل تحديد، <code>Ctrl/Cmd+A</code>)، والنقل (وفق خطوة الالتقاط؛ ويتجاوزها <code>Alt</code>؛ ولا يتغيّر المسار إلا بين أجزاء يجوز أن تتشاركه)، والحذف، والاستنساخ بعد التحديد (<code>Ctrl/Cmd+D</code>)، والتكرار في المكان (<code>Shift+D</code>)، والنسخ والقص واللصق عند مؤشر التحرير (المقطع الذي لا يناسب المسار تُعرض عليه المسارات التي يمكنه الذهاب إليها، ولا يُغيَّر بصمت أبدًا)، وتغيير الحجم من أيٍّ من الحافتين (وتتكرر الحلقة بعد طولها)، والإزاحة (السحب مع <code>Alt</code>)، والتقسيم (<code>S</code>)، والعكس، وإعادة التسمية، واللون، و<em>إعادة إلى الخطة</em> — من قائمة السياق أيضًا. ويُسمع المقطع المنقول أو المُزاح أو المعكوس من موضعه في الحلقة الملتقَطة.","changelog.91d85c02a166":"<strong>تلاشٍ مطابق تمامًا لعرض توزيع الأغنية في MIDI Master</strong>: ثلاثة مقابض لكل جانب — الطول على الحافة العليا للمقطع، والانحناء على خط التلاشي نفسه — لا تتقاطع أبدًا، أيًّا كان طول المقطع؛ وأقصر مقطع يساوي نوتة 1/64.","changelog.c0ccdbacbd8c":"<strong>المُخفِتات.</strong> مقبض مستوى على المقطع نفسه (من −∞ إلى +6 dB، و<code>Shift</code> للضبط الدقيق، والنقر المزدوج للعودة إلى 0 dB)، ومُخفِتات الأجزاء في وحدة التحكم ومُخفِت رئيسي — وفق قانون مُخفِت واحد — يُسمع كل تحريك أثناء السحب، ويصبح خطوة تراجع واحدة عند انتهائه.","changelog.2bcc3000b0a9":"<strong>مسارات أتمتة</strong> لمستوى الصوت، والتوزيع الستيريو، والعرض، وتردد قطع التمرير المنخفض والعالي، والرنين، وإرسال الصدى والتأخير، والتشبّع، وتقليص البتات، وعمق البوابة، وطبقة الصوت على كل جزء، ولمستوى الصوت الرئيسي والتمرير المنخفض الرئيسي — تُرسم وتُثنى وتُحدَّد وتُنقل؛ وأختام أشكال (منحدرات، ومنحنى S، وجيبي، ومثلث، ومربع، وسن المنشار، وخطوات عشوائية) ونسخ نطاق ولصقه؛ ويُحرَّر مسح الحركة نفسها أو غطستها على المسار الذي تُعزف عليه. تُقرأ عيّنةً بعيّنة، في العزف المباشر وفي التصيير على حدٍّ سواء.","changelog.7d436c4c3696":"<strong>الأقسام.</strong> الإدراج، والحذف، والسحب لإعادة الترتيب (ينتقل كل ما في القسم معه)، وتغيير الطول، وتغيير النوع (يُعاد سحب نشاطه للنوع الجديد)، وإعادة التسمية، والقفل — من قائمة القسم أو من ترويسته.","changelog.48c0b2ee5ed9":"<strong>القفل وإعادة السحب.</strong> لا تمسّ إعادة السحب أبدًا قسمًا مقفلًا أو مقطعًا مُحرَّرًا، ولا تحرّك أبدًا ما يجاوره؛ وتعرض <em>ما الذي تغيّر</em> كل جزء وحركة غيّرتها، قسمًا قسمًا.","changelog.e101a7e88895":"<strong>الحركات يدويًا.</strong> لوحة بكل الحركات (تتصدّرها حركات النموذج نفسه)، تُوضع وتُسحب وتُمدَّد وتُحذف على شريط العلامات؛ وتحرّر لوحة خصائص الحركة مُعاملاتها وأجزاءها وتتيح الاستماع إليها أثناء المعاينة — مبنيّة تمامًا كما يبني المُخطِّط الحركة.","changelog.48cc96242f52":"<strong>تراجع وإعادة بلا حدود</strong> لكل تغيير في عرض توزيع الأغنية، تحتفظ بهما النسخة ويُحفظان مع المشروع، من زرَّي «تراجع» و«إعادة» في الترويسة (وكلٌّ منهما يسمّي خطوته) أو <code>Ctrl/Cmd+Z</code> و<code>Ctrl/Cmd+Shift+Z</code> و<code>Ctrl+Y</code>. <strong>آمن من الانهيار:</strong> يُكتب كل تغيير فورًا في مجلد بيانات التطبيقات (بعيدًا عن خيط البرنامج المضيف نفسه)، والبرنامج المضيف الذي أُغلق قبل الحفظ يُعيد فتح المشروع على آخر تغيير أجريته، ويخبرك بذلك — مع <em>الاحتفاظ بالنسخة المحفوظة</em> لحالة كان فيها التغيير يخص نسخة أخرى (مشروعًا أقدم أُعيد فتحه بعد <em>حفظ باسم</em>). والمسار المكرَّر يحتفظ بحفظ تلقائي خاص به.","changelog.4a2ef5527abc":"<strong>المقطع الذي يغيّره البرنامج المضيف يُعيد ملاءمة التوزيع.</strong> طول المقطع الجديد أو الميزان الجديد يضع تعديلاتك عليه كما يفعل الاستيراد، بدلًا من التخلي عنها؛ ويبدأ التراجع من جديد من هناك.","changelog.7e8282605542":"<strong>الشبكة والنظافة.</strong> الالتقاط إلى المازورة أو النبضة أو 1/8 أو 1/16 أو ثلاثياتها، أو إيقافه؛ والتكبير مع خريطة مصغّرة؛ وتظليل الجمل الموسيقية بطول 4/8/16 مازورة؛ وتلاشٍ متقاطع تلقائي بطول 3 ms حيث تلتقي المقاطع؛ ومع إيقاف الالتقاط، تُزاح الحافة إلى أقرب نقطة عبور صفري في الحلقة (في حدود 1 ms). لا تُحدث أي سلسلة من التعديلات طقطقة.","changelog.9ed31073c953":"<strong>رفّ التوزيعات.</strong> مقطع واحد، وتوزيعات مُسمّاة كثيرة، من قائمة «التوزيع» في الترويسة: <em>توزيع جديد</em>، و<em>تكرار</em>، و<em>إعادة تسمية</em>، و<em>حذف</em> (قابل للتراجع)، و<em>تبديل</em> — عند خط المازورة التالي أثناء التشغيل، وفورًا عند التوقف — و<em>مقارنة</em>، وهي مفتاح A/B بين أي توزيعين؛ وأربع لقطات (A–D) داخل كلٍّ منها. لا يعيد التبديل أبدًا التقاط المقطع أو فك ترميزه، والتوزيع الذي تبدّل عنه ثم تعود إليه يبقى كما كان تمامًا. كل عملية على الرف خطوة تراجع واحدة، ويحمل ملف <code>.unloop</code> الرف كاملًا.","changelog.04b5ecf4f4ca":"<strong>ملفات التوزيع <code>.unarr</code>.</strong> يكتب <em>تصدير التوزيع…</em> توزيعًا واحدًا دون مقطعه المتكرر؛ ويضعه <em>استيراد توزيع…</em> فوق المقطع المتكرر المفتوح لديك — فيجد أقسامه ومقاطعه وحركاته ومساراته بحسب ماهيتها (اللازمة الثانية، طبول المقطع الغنائي)، والأقسام المبنية من دورات كاملة تُقاس على طول المقطع الجديد — ويعرض كل ما لم يجد له مكانًا.","changelog.900ccf7596b0":"<strong>لوحة المفاتيح أولًا.</strong> جدول واحد للاختصارات يقود التطبيق ويكتب قائمتها — اضغط <code>?</code> في Unloop، أو راجع موقع الوثائق. كل تعديل في الخط الزمني يعمل دون فأرة: تنقّل بين المقاطع، وانقلها بخطوة الالتقاط، وغيّر حجمها، وغيّر مستواها، وأمسك مقابض تلاشيها، وقسّم، واعكس، واقفل، وافتح قوائمها. تعمل مفاتيح الخط الزمني حين يكون التركيز على الخريطة (أو على لا شيء)، ولا تعمل أبدًا على زر أو مسار أو مربع حوار عليه التركيز. والخريطة مُسمّاة وموصوفة لقارئات الشاشة، مقطعًا مقطعًا ومقبضًا مقبضًا.","changelog.2a6141e43be0":"التغييرات","changelog.7757cf2e3226":"<strong>حالة المشروع بالمخطط 6، ومستند <code>.unloop</code> بالمخطط 2</strong>: التعديلات، والسجل، والرف، وتعديلات كل توزيع ولقطاته. وتُفتح المشاريع والملفات الأقدم كما كانت.","changelog.852a0be917e2":"<strong>تنتقل حزم Freally المشتركة إلى <code>shared-v5</code></strong> — من <code>shared-v3</code> في MIDI Master إلى <code>shared-v5</code>، مع تفرّع nih-plug الخاص به عند <code>df472391</code>: تبقى صفحة المحرّر تحت نافذتها حين تُحرَّك النافذة (إذ يُبلَّغ WebView2 بأن النافذة تحرّكت ويُعاد وضعه تحتها)، ويتوفر <code>freally-extract</code> و<code>process_mode()</code> من nih-plug، وتُعاد لقطة القائمة عند الوسم الجديد (بياناتها لم تتغيّر).","changelog.fb1d01817381":"<strong>المستودع عام</strong> — <code>MikesRuthless12/freally-unloop</code>، جميع الحقوق محفوظة؛ وتأتي الحزم المشتركة من المستودع العام <code>MikesRuthless12/freally-midi-master</code>، ولا يحتاج بناء إصدار macOS إلى أي سر.","changelog.01c79b299c9b":"<strong>يعمل التكامل المستمر على GitHub</strong>، على Windows وLinux وmacOS، مع كل دفع وكل طلب سحب — كل البوابات، وclap-validator وpluginval بدرجة صرامة 10 على كل مُشغِّل (وAU على macOS). لم يعد أي إيداع يحمل <code>[skip ci]</code>.","changelog.8c8f3f1edad1":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-09-28\">2026-09-28</time></span><span class=\"release__title\">C: الالتقاط والمعاينة والتصيير</span>","changelog.3ccc718cc694":"اكتمل الـ MVP. تلتقط كل نسخة دورة واحدة من مقطعها وتعزف المقطوعة من الذاكرة؛ ويُعايَن التوزيع كاملًا داخل Unloop بينما الـ DAW متوقف؛ ويُصيّره زر <strong>تصيير</strong> — مزيجًا أو مسارات منفصلة أو جزءًا أو قسمًا — بصيغة WAV أو AIFF أو FLAC أو MP3، مطابقًا عيّنةً بعيّنة لما سمعته مباشرةً؛ ويُفلته حامل السحب مباشرةً على مساراتك؛ ويُكتب إيصال بجانب كل ملف؛ ويُحفظ المقطع كمشروع <code>.unloop</code> يمكنك إعادة فتحه، أو العثور عليه مجددًا في مكتبة المقاطع مع بقية مقاطعك.","changelog.b88c7903914f":"<strong>الالتقاط.</strong> بعد <em>إنشاء</em>، تسجّل كل نسخة دورة واحدة بالضبط من مقطعها — <code>loop_bars</code> من الموسيقى بدءًا من حدّ الدورة التالي، بدقة العيّنة عند 44.1 و48 و96 kHz — مباشرةً من مدخل الـ DAW، لا من مخرج Unloop نفسه أبدًا. وتوضّح شارة <strong>مباشر / مُلتقَط</strong> بجانب أزرار المعاينة الحالة (انتظار، التقاط، مُلتقَط، متقادم) مع <em>إعادة الالتقاط</em> و<em>انسَ الالتقاط</em>. الإيقاف أو القفز أو تغيير الإيقاع في منتصف التسجيل يتخلّص من التسجيل الجزئي ويحاول مجددًا عند التشغيل التالي؛ والمقطع الأطول من 64 ثانية يُرفض مع توضيح السبب كتابةً. تُحفظ الالتقاطات بحسب محتواها (BLAKE3) في مجلد بيانات التطبيقات، حتى 2 GB، ويُحذف الأقدم استخدامًا أولًا؛ ولا يحفظ مشروع البرنامج المضيف إلا البصمة، والمشروع الذي اختفى التقاطه يطلب منك تشغيل المقطع مرة واحدة.","changelog.b3429b1f4985":"<strong>تغيّر المقطع — إعادة الالتقاط؟</strong> حين لا يكون المقطع الوارد هو المقطع الملتقَط لدورتين متتاليتين (بمقارنة نطاقًا نطاقًا)، تقول الشارة ذلك. لا يُستبدل شيء أبدًا أثناء التشغيل؛ وإعادة الالتقاط قرارك أنت، بضغطة منك.","changelog.09d9a80b48ef":"<strong>العزف من الذاكرة.</strong> بمجرد الالتقاط، تعزف النسخة المقطوعة من التقاطها، مقفلةً على موضع البرنامج المضيف — بلا انجراف في مقطع لا تساوي دورته عددًا صحيحًا من العيّنات، وبتلاشٍ متقاطع حين يتغيّر المصدر، ومع بقاء التأخير المُضاف صفرًا. تقرأ حركات الذاكرة الالتقاط؛ وقبل وجوده تقرأ الماضي القريب للمقطع، وتقول الخريطة ذلك.","changelog.2d3fbd1189a2":"<strong>المعاينة داخل Unloop.</strong> حين يكون البرنامج المضيف متوقفًا، تعزف أزرار التشغيل والإيقاف المؤقت والإيقاف والتكرار في القسم الرئيسي (أو مفتاح المسافة) المقطوعة كاملة في Unloop — كل النسخ على القناة معًا، كلٌّ من التقاطها، على العيّنة نفسها داخل DAW واحد وفي حدود كتلة واحدة عبر العمليات. انقر مسطرة الخريطة للقفز؛ وكرّر قسمًا. اضغط تشغيل في البرنامج المضيف فيتولّى الأمر فورًا — تتوقف المعاينة مؤقتًا حيث كان الصوت وتقول ذلك. وتُسمّى الأجزاء التي لا يشغّلها البرنامج المضيف وهو متوقف (المسارات غير الحية في Logic) والأجزاء التي لم يُلتقط لها شيء بعد.","changelog.5f7f65713c74":"<strong>الحركات II</strong>: العكس، ونصف الإيقاع (شريط وتمديد)، والبوابة، والصوت منخفض الدقة، ورمية الصدى (بصدى Unloop الخاص)، ورمية التأخير (ثُمن منقوط، بينغ بونغ)، وغطسة الطبقة، والترجيع — لكلٍّ منها اختبارات توقيت وطقطقة واستهلاك معالج خاصة بها. تُعزف أقسام نصف الإيقاع الآن (من الالتقاط، وبالسرعة الكاملة إلى أن يوجد). أربع حركات معًا — أيٌّ من الجديدة بينها — تكلّف نواة الصوت كاملة ≈25–27 µs من كتلة بطول 128 عيّنة عند 48 kHz: نحو 1 % من نواة معالج واحدة، ضمن ميزانية 1.5 %.","changelog.aae38e7e09b4":"<strong>التصيير.</strong> تُصيَّر المقطوعة خارج الزمن الحقيقي من الالتقاطات عبر الشيفرة نفسها التي تعزفها مباشرةً — مسار منفصل لكل جزء، قبل المُخفِت وبالطول الكامل بدءًا من المازورة 1 كي يصفّها أي DAW، والمزيج كمجموعها. ويُلزَم العزف المباشر والتصيير بالتطابق باختبار لكل حركة جديدة ولمقطع نصف الإيقاع — بتًّا ببت في كتل التصيير نفسها، وفي حدود −100 dB لحركات الذاكرة في أحجام الكتل الأخرى التي قد يعزف بها البرنامج المضيف؛ والتصيير مرتين يعطي البايتات نفسها. يستغرق تصيير مقطوعة مدتها ثلاث دقائق بثمانية مسارات منفصلة نحو 3 ثوانٍ، مع شريط تقدّم لكل ملف وزر <strong>إلغاء</strong> الذي لا يترك أي أثر.","changelog.30dab5974741":"<strong>WAV وAIFF وFLAC وMP3.</strong> WAV بدقة 16/24 بت أو 32 بت عائم مع قطعة <code>acid</code> في كل عمق، فيضبطه Ableton وFL وAcid تلقائيًا على إيقاعك؛ وAIFF بدقة 16/24 (لا مكان فيه لحمل الإيقاع، ويقول مربع الحوار ذلك)؛ وFLAC بدقة 16/24 مع وسم <code>BPM</code>؛ وMP3 بمعدل 128–320 kbps مع وسم <code>TBPM</code> (وملاحظة بأن MP3 يضيف تأخير الترميز — استخدم WAV أو FLAC للمسارات المنفصلة التي يجب أن تتطابق). معدل العينات كما التُقط أو 44.1/48/88.2/96 kHz (وMP3 بحد أقصى 48)، ويُحوَّل قبل أن تذكره الترويسة؛ وديثر TPDF ذو بذرة عند خفض عمق البت، مطابق في كل تصيير. وتُقرأ كل صيغة مرة أخرى عبر مفكك ترميز Unloop نفسه في اختباراتها.","changelog.3cff712e7690":"<strong>مقياس التصيير ومحدِّد أمان.</strong> الذروة (dBFS)، والذروة الحقيقية (dBTP) بفرط اعتيان 4×، والجهارة المتكاملة (LUFS، وفق ITU-R BS.1770-4) للمزيج، تُعرض عند انتهاء التصدير؛ ومحدِّد اختياري عند −1 dBTP على المزيج فقط، يُبلغ بمقدار ما خفّض المزيج.","changelog.f311d0c466d8":"<strong>مربع حوار التصدير</strong> (<strong>تصيير</strong> في القسم الرئيسي): المحتوى — المزيج، أو المسارات المنفصلة، أو أيٌّ من الأجزاء، أو قسم، أو المقطوعة كاملة — والصيغة، والجودة، والمعدل، والديثر، والمحدِّد، والإيصالات، وأسماء الملفات التي سيكتبها، معروضةً مباشرةً من قالبك عبر الشيفرة نفسها التي تسمّي الملفات. القالب الافتراضي هو <code>{genre} - {mode} - {what} - {bpm} BPM - {key}</code>؛ و<code>{model}</code> موجود إن أردت الاسم فيه. <strong>لا يحمل أي اسم ملف افتراضي أبدًا اسم فنان أو منتج</strong> — ويمرّ اختبار على كل اسم في القائمة، وكل نمط، وكل تصدير ليضمن ذلك.","changelog.361d5bae41fd":"<strong>حامل السحب.</strong> اسحب المزيج، أو المسارات المنفصلة، أو جزءًا واحدًا، أو قسمًا واحدًا إلى مساراتك (WAV بدقة 24 بت افتراضيًا)؛ تُصيَّر الملفات قبل بدء السحب، فيصل الإفلات كاملًا.","changelog.8552eba608bc":"<strong>الإيصالات، مفعّلة افتراضيًا.</strong> <code>&lt;name&gt;.unloop-receipt.json</code> بجانب كل تصدير وكل سحب: إصدارا Unloop ومجموعة البيانات، ووسم Freally MIDI Master، والنموذج والنمط والبذرة، وبصمة الخطة، وبصمة التقاط كل جزء، والملفات وما طُلب — ما يكفي لصنع المقطوعة نفسها مرة أخرى. إيقافها تفضيل تختاره، لا إعداد افتراضي أبدًا.","changelog.385eadae4891":"<strong>مشاريع المقاطع (<code>.unloop</code>).</strong> <em>احفظ مشروع المقطع…</em> و<em>افتح مشروع مقطع…</em> من زر المجلد في بداية الترويسة: المقطع محفوظًا مرة واحدة (أجزاؤه بصيغة FLAC بدقة 24 بت) والتوزيع فوقه. حفظ المشروع نفسه مرتين يعطي البايتات نفسها؛ وفتحه يعطي الخطة نفسها، حتى البصمة، والالتقاط نفسه دون تشغيله من جديد. ويُرفض كاملًا المشروع الصادر عن إصدار أحدث من Unloop («صُنع بإصدار أحدث من Unloop — حدّث لفتحه»)؛ وإذا كان جزء مفقودًا أو تالفًا يُفتح الباقي ويُسمّى الجزء المطلوب توفيره من جديد. لا يستبدل الحفظ أي ملف أبدًا — الاسم المأخوذ يُضاف إليه <code> (2)</code> — وإعادة حفظ مشروع تحتفظ بكل ما فيه مما لم تصنعه هذه النسخة.","changelog.a86b818719c2":"<strong>مكتبة المقاطع.</strong> أضف مجلدات مقاطعك: يُدرج كل ملف <code>.unloop</code> وكل ملف WAV وAIFF وFLAC وMP3 وMIDI فيها مع مازوراته، وBPM (<em>من الملف</em> — من قطعة <code>acid</code> أو وسومه أو اسمه — إلى أن يصل الاكتشاف في <code>v0.7.0</code>)، ووسومه، وعدد مرات توزيعه، وآخر تعديل، وشكل موجي مصغّر. ابحث وصفِّ حسب BPM أو السلّم أو الوسم أو <em>لم يُوزَّع قط</em>؛ وانقر سطرًا لتسمعه (<code>↑/↓</code> للتنقل، و<code>Esc</code> للإيقاف) — داخل Unloop فقط، دون تحريك موضع التشغيل في الـ DAW أبدًا — ثم <strong>وزّع</strong> حين يكون مقطعًا واحدًا تمامًا. تُفهرَس ألفا ملف في ثانية أو ثانيتين، بعيدًا عن خيط البرنامج المضيف. ولا تفعل المكتبة سوى قراءة مجلداتك. تُدرج مقاطع MIDI الآن وتصبح قابلة للتوزيع في <code>v0.7.0</code>.","changelog.a26b2595dfc9":"<strong>المشاريع الأخيرة</strong>، الأحدث أولًا، بنقرة واحدة لإعادة الفتح؛ والمشروع الذي نُقل يظهر على أنه مفقود مع <em>أزل من القائمة</em> (السطر، لا الملف أبدًا).","changelog.2e4a3278fa31":"<strong>قاطع المقاطع</strong> — <em>اصنع مقطعًا من ملف أطول…</em>: اختر مازورة البداية وطولًا (1 أو 2 أو 4 أو 8 أو 16 مازورة) بإيقاع معيّن، واستمع إلى الجزء المقتطع وهو يتكرر، ثم <em>وزّع</em> لتوزيعه كمشروع مقطع جديد. القطع دقيق حتى العيّنة، ولا يتغيّر الملف المصدر أبدًا.","changelog.22f2979096ba":"<strong>لوحة الناقل</strong> تعرض النسخ التي تحمل التقاطًا، والنسخ التي لا يشغّلها البرنامج المضيف أثناء تشغيل المعاينة.","changelog.d0c12bfcdf93":"<strong>تغيّرت كل بصمات الخطط — ولم تتغيّر الخطط.</strong> تسمّي الخطة وسم Freally MIDI Master الذي استُوردت بياناتها عنده (<code>mm-shared-v2/…</code>، وكان <code>mm-shared-v1/…</code>)؛ والبيانات لم تتغيّر، لذا يوزّع كل اسم ونمط وبذرة تمامًا كما من قبل. ولم تتغيّر الخطط المرجعية الـ 24 إلا في سطر ترويستها.","changelog.81dd6b6d682d":"<strong>تنتقل حزم Freally المشتركة إلى <code>shared-v2</code></strong> — <code>freally-encode</code> من MIDI Master (كل بايت في كل ملف مُصدَّر) و<code>freally-drag</code> (السحب الأصلي على Windows وmacOS وLinux)، وقد فُصلا عن MIDI Master من أجل Unloop، إلى جانب المحرّك ومُحوِّل webview عند الوسم نفسه. يُبنى المحرّك الآن وحده، فزال الحل الالتفافي القائم على سحب المستودع كاملًا في CI الخاص بـ Linux.","changelog.25e088b374a9":"<strong>مؤدٍّ واحد لكل المخرجات.</strong> انتقل الجدول الزمني والمؤدّي إلى حزمة خاصة بهما، <code>performance</code>، يمرّ عبرها العزف المباشر والمعاينة والتصيير جميعًا؛ وتضم <code>render</code> التصيير، والمدخل الأمامي للمرمِّزات، ومفكك الترميز، والمقياس، والمحدِّد، وحاوية <code>.unloop</code>.","changelog.759e88328427":"<strong>ينتقل تخطيط ملف الناقل إلى 2</strong> (<code>&lt;letter&gt;.v2.mmap</code>)، حاملًا بصمة التقاط كل نسخة وساعة معاينة القناة. لا يتشارك Unloop <code>v0.4.0</code> وهذا الإصدار قناةً عبر العمليات أبدًا — حدّث كل النسخ معًا. ويُفتح هنا مشروع البرنامج المضيف المحفوظ بـ <code>v0.4.0</code> (تنتقل حالته إلى المخطط 4، الذي يشير إلى الالتقاط)؛ أما المشروع المحفوظ هنا فيرفضه <code>v0.4.0</code> كاملًا.","changelog.2d5e534dd29f":"<strong>تنزلق تغييرات المستوى على مدى 2 ms</strong> (وكانت 5 ms)، فتحتفظ حواف البوابة السريعة بشكلها؛ ولا تزال كل حافة تجتاز اختبار الطقطقة عند −60 dB.","changelog.ddd7a1094504":"<strong>يطوي البحث حروفًا مثل Ø وß وŁ</strong>، فتجد «mo» الاسمَ MØ.","changelog.f6ed90cd965e":"<strong>القسم الرئيسي في وحدة التحكم</strong> يكتسب أزرار المعاينة، وشارة المصدر، و<strong>تصيير</strong>، وحامل السحب؛ ويعرض عدّاد الشريط <em>قيد المعاينة</em> أثناء تشغيل المعاينة؛ وتبدأ الترويسة بزر مجلد مشروع المقطع.","changelog.044bd3e3ee09":"يدرج <code>THIRD-PARTY-NOTICES.md</code> الآن 437 مكوّنًا (وكانت 381): من بينها مفكك الترميز (Symphonia، بترخيص MPL-2.0 — وهو مفكك ترميز، تسمح به سياسة التراخيص)، ومرمِّزا FLAC وMP3، ومُعيد الاعتيان، ومربعات حوار الملفات الأصلية.","changelog.1246fc93bca0":"الإصلاحات","changelog.cbcb91b5782e":"<strong>يحتفظ محرّر Unloop بملف تعريف متصفح خاص به</strong> (<code>%APPDATA%\\Freally Unloop\\webview</code>، وما يقابله على macOS وLinux)، ولم يعد يستخدم مجلد Freally MIDI Master: فقد كان تشغيلهما جنبًا إلى جنب قد يترك أحد المحرّرين فارغًا («المورد المطلوب قيد الاستخدام»).","changelog.8f6fb4eb7f42":"الأمان","changelog.250423c9e9f8":"من مراجعة الشيفرة والأمان لهذه المرحلة:","changelog.075cc32b4202":"<strong>يُقرأ كل ملف على أنه عدائي</strong> — ملف <code>.unloop</code>، أو مقطع في المكتبة، أو التقاط مخزَّن مؤقتًا، أو تفضيل: يُحدّ حجمه قبل قراءته، ويُتحقق من كل طول مقابل البايتات الموجودة فعلًا قبل تخصيص أي ذاكرة بناءً عليه، ويُرفض بدلًا من التخمين. لا ينهار مفكك الترميز ولا قارئ المشاريع أبدًا أمام ملف (وتُلزمهما بذلك اختبارات البايتات العشوائية والأطوال الكاذبة)، وتُفك ترميز أجزاء المشروع واحدًا تلو الآخر، فقط عند استخدام أحدها، فلا يستطيع ملف عدائي صغير أن يجعل البرنامج المضيف يحتجز غيغابايتات.","changelog.e574701848b3":"<strong>لا شيء يلمس الشبكة.</strong> يُرفض المجلد المشترك على الشبكة (<code>\\\\server\\share</code>) أو مسار الجهاز قبل أن يلمسه أي شيء؛ ويُرفض المشروع أو المقطع أو مجلد المقاطع أو مجلد التصدير الموجود على محرك أقراص شبكي معيَّن قبل فتح أي ملف عليه أو حتى النظر إليه (فالنظر اتصال)؛ ويُرفض مجلد التصدير الذي يؤدي إلى مجلد مشترك — عبر رابط أو نقطة وصل إليه — قبل كتابة أي شيء.","changelog.24ed701d1a3d":"<strong>لا يُستبدل شيء ولا يُترك شيء مكتوبًا نصف كتابة.</strong> اسم الملف المأخوذ يُضاف إليه <code> (2)</code>؛ وتُكتب الملفات بجانب مكانها ثم تُنقل إليه، والتصدير الذي يفشل أو يُلغى يسترجع ما كتبه. وأسماء الملفات أسماء بسيطة على كل نظام (بلا أسماء أجهزة، وبلا فواصل مسارات).","changelog.d189c3bc173c":"<strong>البرنامج المضيف الذي يُلغي تحميل Unloop بينما لا يزال أحد خيوطه يعمل</strong> — مربع حوار ملفات مفتوح، أو تصدير في منتقي المجلدات — لا ينهار على Windows: فكل خيط من هذا النوع يُبقي المكوّن الإضافي محمّلًا حتى آخر تعليمة فيه.","changelog.a3c71b90162b":"قيود معروفة","changelog.c8a83adf7aa9":"فحوصات البرامج المضيفة لـ <code>v0.5.0</code> — الالتقاط، والمعاينة، والتصيير، والصيغ، والسحب إلى الخارج في FL Studio وAbleton Live وReaper — مكتوبة (<code>Live-To-Do.md</code> § 4) ولم تُجرَ يدويًا بعد؛ والسحب إلى الخارج على macOS وLinux مكتوب لكنه لم يُفلَت بعد في DAW حقيقي.","changelog.fff6674de28f":"لا يعرض السحب بعدُ صورةً لما تسحبه.","changelog.342624d6fcd1":"تُقطع رمية الصدى أو التأخير في المازورة الأخيرة عند خط المازورة الأخير للمقطوعة؛ ولا يستمر رنين التصيير بعده.","changelog.b11de52e56ae":"تبقى مُخفِتات الأجزاء عند مستوى الوحدة في المزيج إلى أن تصل مُخفِتات وحدة التحكم (<code>v0.6.0</code>)؛ ويحمل مشروع المقطع توزيعًا واحدًا إلى أن يصل الرف.","changelog.7b2349c31bb6":"لا يُعرف سلّم المقطع إلى أن يصل الاكتشاف (<code>v0.7.0</code>)، لذا تُغفل أسماء الملفات الافتراضية <code>{key}</code> حتى ذلك الحين.","changelog.2abf238bf14a":"على شاشة ثانية بمقياس عرض مختلف، يحدّد المحرّر حجمه وفق الشاشة الرئيسية.","changelog.f56d1c79ff84":"على macOS، لا شيء بعدُ يُبقي المكوّن الإضافي محمّلًا أثناء عمل مربع حوار أو تصدير (<code>SECURITY.md</code>، <em>القيود المعروفة</em>).","changelog.13da7fa23214":"يُطرح <code>v0.5.0</code> لـ Windows وLinux فقط؛ ولا يُبنى له أي إصدار لـ macOS (لا AU ولا CLAP ولا VST3 ولا تطبيق مستقل).","changelog.adb870b6c393":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">R: الأدوار والمايسترو</span>","changelog.277edf17b8c6":"ضع Unloop على مسار كل جزء فتعزف النسخ مقطوعة واحدة معًا. النسخة الأولى تقود؛ وكل نسخة أخرى تتبع خطتها حتى العيّنة الواحدة ولا تعزف إلا حركات جزئها — تنقطع الطبول على ناقل الطبول، والجهير على مسار الجهير — بينما تعرض وحدة التحكم شريطًا لكل نسخة. وأُعيد تصميم المحرّر في الأثناء.","changelog.d40fc08c53e8":"<strong>الأدوار.</strong> تأخذ كل نسخة دورًا — المقطع كاملًا، أو الطبول (أو قطعة واحدة من الطقم)، أو الجهير، أو اللحن، أو اللحن المقابل، أو الأوتار، أو الغناء، أو FX، أو توقيع المنتج — من شريطها أو من لوحة «الأدوار والناقل»، بما في ذلك دور نسخة أخرى من أي نافذة. وتُرقَّم النسختان من النوع نفسه («اللحن 2») وتتشاركان مسارًا. والجزء الذي تكتبه الخطة لدور لم يأخذه أحد يُوسَم على الخريطة بأنه لا يُعزف في أي مكان.","changelog.bfed3623cf95":"<strong>المايسترو.</strong> النسخة الأولى على القناة تقود: تصنع الخطة، وكل نسخة أخرى تتلقى مدخلاتها وبصمتها — لا الصوت أبدًا — وتعيد بناء الخطة نفسها وتُبلغ بالنتيجة. والخطة التي تُغيَّر في أي نافذة تُرسل إلى المايسترو وتصل إلى الجميع. وحين يغيب المايسترو، تتسلّم النسخة التالية العصا في غضون ثانية وتواصل المقطوعة.","changelog.d186a7625d16":"<strong>محاذاة بدقة العيّنة.</strong> تضع كل نسخة كل حافة حركة على العيّنة نفسها، أيًّا كان حجم الكتلة الذي يعمل به مسارها؛ والحركة الخاصة بالطقم التي تُعزف على ناقل الطبول تُقسَّم على نطاقات ذلك الناقل كما كانت مقطوعة النسخة الواحدة ستعزفها.","changelog.0d92b38aa91d":"<strong>مصباح الناقل ولوحة «الأدوار والناقل».</strong> الأخضر: تتشارك النسخ ذاكرة هذا الـ DAW. الكهرماني: يُبقي البرنامج المضيف كل مكوّن إضافي في عملية خاصة به (صندوق Bitwig المعزول، أو الجسر في Reaper، أو الجسر في FL، أو مضيف AU في macOS)، فتلتقي النسخ بدلًا من ذلك عبر ملف صغير لا يصل إليه إلا مالكه — يُقال ذلك ولا يُخفى. الأحمر: نسخة لا تعزف خطة المايسترو، مع <strong>أعد إرسال الخطة</strong>. وأربع قنوات، A–D، تُبقي مشروعين في DAW واحد منفصلين؛ والقناة التي تعزف بالفعل خطة مشروع آخر تقول ذلك وتعرض القناة التالية، أو اتّباع تلك الخطة.","changelog.c4f20b079ad4":"<strong>وحدة التحكم v2</strong>: شريط لكل نسخة، بترتيب الأدوار، بمصابيحه ومقبض مرشحه ومقياس VU ومُخفِته الخاصة، مربوطة بما طبّقه خيط الصوت في تلك النسخة؛ وشريط هذه النسخة محاط بإطار، وعصا المايسترو مضاءة.","changelog.ad55bbaf935b":"<strong>مظهر جديد.</strong> محرّر أغمق وأهدأ: ارتفاع وحافة وتعبئة واحدة لكل عناصر التحكم في الترويسة، وحقل بحث بأيقونته، ومنتقي أنماط مرسوم، وشارة الساعة ملوّنة بدلًا من أن تكون محاطة بإطار، والخريطة الفارغة مرسومة كطيف خط زمني، ووحدة تحكم من ثلاث وحدات — الناقل، وحامل غائر للشرائط مع لوحات أسماء، والقسم الرئيسي مع زر «إنشاء» بعرض كامل.","changelog.c624ea467282":"<strong>داكن افتراضيًا.</strong> يُفتح المحرّر داكنًا أيًّا كان إعداد نظام التشغيل؛ ولا يزال <em>النظام</em> و<em>فاتح</em> في الإعدادات، ويُتذكَّر المظهر الذي تختاره.","changelog.14fe50ad6168":"<strong>كل شيء يتسع، بكل لغة.</strong> لا تخرج أي تسمية من مربعها — اسم الدور الطويل يلتف على لوحته، واسم القسم الطويل على الخريطة يُقطع بعلامة حذف بدلًا من ضغطه — ولا يتمرّر المحرّر أفقيًا أبدًا، حتى في نوافذ أضيق مما ينبغي لأي برنامج مضيف أن يمنحه (برنامج مضيف بمقياس عرض 150 % منحه 930 بكسلًا). وتباعد مسطرة الخريطة بين أرقامها بحسب عرضها المقيس، وتنضغط المسارات أكثر على الخريطة القصيرة كي تظهر الجلسة كاملة، وتحصل أسماء المسارات على المساحة التي تحتاجها.","changelog.6d85908ca753":"<strong>الاسم، مرة واحدة.</strong> تُبلغ كل صيغة بالاسم «Freally Unloop» تمامًا، ولا شيء بجانبه يكرّره، فلا يذكره شريط عنوان البرنامج المضيف مرتين أبدًا.","changelog.696a4fb40d61":"<strong>قد ينهار البرنامج المضيف عند إغلاق Unloop فتحه للتو</strong> — فحص سريع للمكوّنات الإضافية، أو أداة تحقق، أو مشروع أُغلق وهو لا يزال قيد التحميل. فقد كان العامل الخلفي لإطار المكوّنات الإضافية، المشترك بين كل النسخ، يتوقف نهائيًا حين يصادف عملًا تركته نسخة رحلت بالفعل، وكانت النسخة التالية التي تُغلق تُسقط البرنامج المضيف. لم يعد Unloop يعطيه أي عمل: كل نسخة تؤدي عملها على خيط تملكه.","changelog.107aa869557c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">M: اللحظة السحرية</span>","changelog.edddef519a58":"نسخة واحدة من Unloop على إيقاع متكرر تعزف الآن المقطوعة كاملة، مباشرةً: اختر فنانًا أو منتجًا أو نوعًا موسيقيًا، واضغط «إنشاء»، واضغط تشغيل في الـ DAW، فيصبح مقطعك أغنية مُوزَّعة متزامنة مع البرنامج المضيف — أجزاء تنقطع وتعود، ومسح المرشح، وتصاعدات متقطعة، وإيقافات الشريط — بلا طقطقات وبلا أي تأخير مُضاف، بينما تتحرك الخريطة ووحدة التحكم معها.","changelog.c542a3d7af1e":"<strong>العزف المباشر (وضع الحلقة الواحدة).</strong> تقسم نسخة واحدة مقطعك إلى ثلاثة نطاقات — منخفض (أقل من 120 Hz)، ومتوسط، ومرتفع (فوق 4 kHz)، بتقسيم Linkwitz–Riley يعود مجموعه مستويًا — وتعزف الخطة فوقها: يدخل كل نطاق ويخرج حيث تقول المقطوعة، والحركات المكتوبة للمقطع كاملًا تعمل عليه كله. لا يتغيّر شيء في ملف مقطعك.","changelog.f209a2fc6b77":"<strong>أولى الحركات التي يمكنك سماعها</strong>: الكتم، وإلغاء الكتم، والانقطاع، والقطع؛ ومسح المرشح (تمرير منخفض أو عالٍ، وتردد القطع دقيق عند كل وحدة توقيت، ومنحنٍ وفق منحنى الخطة)؛ والتصاعد المتقطع (النبضة السابقة، يُعاد إطلاقها أسرع فأسرع، صاعدةً)؛ وإيقاف الشريط (المقطع يتباطأ حتى يتوقف عند الحد). كل حافة منحدر ناعم (5 ms)، خاضع لاختبار طقطقة عند −60 dB تحت مستوى الموسيقى. وبقية المفردات على الخريطة، موسومة بالإصدار الذي تصل فيه.","changelog.079fb6a04db0":"<strong>متزامن مع البرنامج المضيف، أيًّا كانت طريقة عزفه.</strong> تضع ساعة الأغنية المقطوعة فوق خطك الزمني بدءًا من مازورة تختارها؛ وتعدّ ساعة المقطع المتكرر دورات المقطع — في وضع الأنماط في FL Studio، أو قوس التكرار، أو عرض الجلسة في Ableton — فتكون 200 دورة 200 دورة تمامًا. يختار <em>تلقائي</em> واحدة في كل تشغيل ويذكر السبب على شارة الساعة. وتغيير الإيقاع يُبقي كل حركة على مازورتها.","changelog.dd9565bb9638":"<strong>الإيقاع ملك البرنامج المضيف.</strong> تعرض شارة الإيقاع قيمة BPM في الـ DAW وما إذا كانت تناسب الاسم الذي اخترته — مع عدّ نصف الإيقاع وضعفه وتسمية النسبة — وإن لم تكن كذلك، فالإيقاع المعتاد وأقرب إيقاع ضمن النطاق لتنسخه وتضبطه بنفسك. لا يغيّر Unloop إيقاع الـ DAW أبدًا.","changelog.43c245c305f5":"<strong>البحث</strong> في كل الأسماء الـ 2,413، متسامحًا مع الأخطاء الإملائية كما يفعل بحث Freally MIDI Master («metro bumin» يجد Metro Boomin)، وكل سطر يقول ما هو وكم منه خاص به؛ والاختيارات الأخيرة أولًا؛ و«هل تقصد» حين لا يتطابق شيء. <strong>بطاقة النموذج</strong> قبل أي ضغطة، مع معاينة لشكل النمط على الخريطة الفارغة. <strong>منتقي الأنماط</strong> (مع <em>أي</em>) و<strong>شارة البذرة</strong> — انسخها، أو الصق واحدة لتستعيد تلك المقطوعة.","changelog.c4d42bdbfb75":"<strong>خريطة التوزيع</strong>: الأقسام، ومسارات النطاقات الثلاثة مع تلاشي كل مقطع مرسومًا كما يشكّله الصوت، ورمز لكل حركة، ومنحنى الطاقة، ومسطرة مازورات بالدقائق والثواني، ورأس التشغيل في البرنامج المضيف؛ وتتوهّج الحركة على مساراتها أثناء عزفها. تُبنى الخريطة تدريجيًا حين تصل مقطوعة (يتخطى ذلك مفتاحٌ أو نقرة؛ وتظهر فورًا مع تقليل الحركة).","changelog.b9acf1dcbf7e":"<strong>وحدة التحكم</strong>: شريط قناة تعرض مصابيحه ومُخفِته ومقبض مرشحه ما طبّقه خيط الصوت فعلًا، ومقياس VU باستجابة حقيقية، والقسم الرئيسي — «إنشاء»، و«إعادة السحب»، وعدّاد الشريط، والبذرة. وحين لا يُخبر شيءٌ Unloop بطول مقطعك، يسأل مرة واحدة (2 أو 4 أو 8 أو 16 مازورة) ولا يمنع «إنشاء» أبدًا.","changelog.7e08eeb2a0b2":"<strong>المشاريع تتذكّر.</strong> يُحفظ الاسم والنمط والبذرة وطول المقطع والجلسة في مشروع الـ DAW؛ وإعادة فتحه تصنع المقطوعة نفسها مجددًا — الخطة نفسها، حتى البصمة — وتغيُّر طول المقطع أو الميزان الإيقاعي (بإجابتك، أو بقوس التكرار في الـ DAW) يعيد صنع الخطة وفقه.","changelog.cac34fa81c8b":"<strong>يُفحص اسم كل نموذج ونوع موسيقي ونمط مقابل خطوط Noto المضمَّنة</strong>، كما كانت الترجمات تُفحص من قبل، فلا يمكن لأي اسم تعرضه القائمة أن يلجأ إلى خط النظام أو إلى مربع حرف مفقود.","changelog.7962b5beebac":"<strong>التجاوز</strong> يُخفي بنعومة العزفَ <em>وأيضًا</em> ضبطَ مستوى المخرج معًا، ثم يمرّر صوتك دون مساس؛ وتقرأ المقاييس ما يغادر المكوّن الإضافي فعلًا، بعد ضبط المستوى.","changelog.ec1231a741d1":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-24\">2026-09-24</time></span><span class=\"release__title\">P: المُخطِّط</span>","changelog.475985e8de84":"يتحوّل الآن أيٌّ من الأسماء الـ 2,413 إلى خطة توزيع حتمية. لا شيء يعزفها بعد — فأول عزف مباشر في <code>v0.3.0</code> — لكن كل قرار تحتاجه المقطوعة يُتخذ هنا، على الشبكة، قبل أن تُعزف أي عيّنة.","changelog.79a17b028e4f":"<strong>المُخطِّط.</strong> يصبح الاسم والنمط والجلسة والبذرة مقطوعة كاملة: شكل الأغنية، وطول كل قسم على شبكة الجمل الموسيقية بطول 4/8/16 مازورة، والأجزاء التي تُعزف في كل قسم وكيف (الهاي هات فقط، أو مع مرشح، أو بتلاشٍ، أو بنصف الإيقاع)، وكل حركة موضوعة بدقة وحدة التوقيت — الانقطاعات، والقطع، والتصاعدات المتقطعة، واللفات، والمسح، وإيقافات الشريط، وتبديلات الإيقاع، ومؤثرات الانتقال، واللمسات السمعية، وتوقيع المنتج — ومنحنى طاقة مازورةً بمازورة. المدخلات نفسها تعطي الخطة نفسها، بايتًا ببايت، مختومةً ببصمة خطة BLAKE3. ويخطط مقطوعة مدتها ثلاث دقائق في أقل من ملّي ثانية.","changelog.989666ca013f":"<strong>يُوزَّع كل نوع موسيقي بأكثر من طريقة.</strong> الأنماط — نسخة الإذاعة، ونسخة المكستيب، ونسخة النادي/DJ، والتبديل المفاجئ، والبسيط، والمجرّد، والممتد، وأنماط خاصة بأنواع معيّنة (الكلاسيكي، والنسخة الجماعية، وشريط الإيقاعات لـ boom bap؛ والإيقاع البطيء والفاصل لـ 2000s R&amp;B؛ والنسخة الصوتية لـ liquid drum &amp; bass). يختار <em>أي</em> نمطًا بحسب وزنه.","changelog.5de91eed2226":"<strong>أول 12 نموذجًا للأنواع الموسيقية</strong>، مؤلَّفة من أبحاث التوزيع: trap وdark trap وplugg وpluggnb وrage وUK drill وNY drill وboom bap و2000s R&amp;B و2020s pop وcountry-pop وliquid drum &amp; bass — 39 نمطًا — إضافةً إلى النموذج الافتراضي الذي يقوم عليه كل اسم آخر.","changelog.a883b8d3cf75":"<strong>القائمة كاملة، مستوردة.</strong> 2,413 اسمًا — 1,507 فنانًا، و833 منتجًا، و73 نوعًا موسيقيًا — من مجموعة بيانات Freally MIDI Master عند الإصدار المثبَّت، مع أسمائها البديلة وحقبها وأنواعها ووراثتها وإيقاعها وأشكال أغانيها. والاستيراد قابل لإعادة الإنتاج حتى البايت، وكل حقل لا يقرأه يُبرَّر غيابه كتابةً.","changelog.8f2f1aef5133":"<strong>شارة صادقة على كل اسم.</strong> <em>رئيسي</em> (له نموذجه الخاص)، أو <em>قياسي</em> (يعزف أشكال أغانيه أو أطوال أقسامه الخاصة — 1,157 اسمًا)، أو <em>موروث</em> (من نوعه الموسيقي — 1,244 اسمًا)، مستمدّة مما استخدمه المُخطِّط فعلًا.","changelog.33b91bcddab0":"<strong>أعد سحب شيء واحد.</strong> يمكن للخطة أن تعيد سحب لمساتها السمعية فقط، أو أجزاء قسم واحد، ويبقى كل ما عدا ذلك كما كان تمامًا.","changelog.fc97f471bb4b":"<strong>الجاهزية لوضع الحلقة الواحدة.</strong> كل حركة تقول ما ستفعله بها نسخة واحدة تقسم مقطعًا واحدًا إلى ثلاثة نطاقات، وحين يتعيّن على نطاق أن ينوب عن جزء لا يمكنها عزله، تقول الخطة ذلك.","changelog.cba5495f6089":"<strong>بطاقة النموذج</strong>: الأنماط، والأشكال، وأطوال الأقسام، والحركات المميزة، والطاقة المعتادة، والإيقاع، والوراثة، والمصدر — محسوبة مما يؤديه المُخطِّط، مع إخلاء المسؤولية.","changelog.88d2b1cd382c":"<strong><code>unloopc</code>، مُصرِّف مجموعة البيانات</strong> — <code>validate</code> و<code>stats</code> و<code>coverage</code> و<code>distinct</code> و<code>card</code> و<code>plan</code> و<code>import-roster</code> و<code>schema</code> — و<code>npm run dataset:*</code>. ويُولَّد مخطط النماذج وملف المفردات من أنواع Rust.","changelog.b582568bbaf2":"<strong>البوابات</strong>: استيراد القائمة، والمخطط، وكل نموذج (<code>ci:local</code> و<code>ci:linux</code>)؛ وكل مفتاح مؤلَّف يقرؤه المُخطِّط — مع إثبات أن كلًّا منها يغيّر الخطة حين يتغيّر؛ وكل نص مؤلَّف يُحلَّل بمفرداته؛ ونمطان متمايزان أو أكثر لكل نوع موسيقي؛ و24 خطة مرجعية؛ والقائمة كاملة تُخطَّط مرتين وتُقارَن؛ وميزانية تخطيط قدرها 50 ms عند المئين 95؛ وكل موضع <code>unsafe</code> في المكوّن الإضافي مقيَّد بالقائمة الموثّقة. وقد رُوقبت كل بوابة وهي تفشل قبل الوثوق بها.","changelog.c83336253c11":"<strong>الملاحظة تحت «إنشاء»</strong> تقول الآن إنه يصل في البناء التالي — فالمُخطِّط الذي كان ينتظره قد وصل، ويُوصَل الزر في <code>v0.3.0</code> — بكل اللغات الـ 18.","changelog.5a7a1b20ab13":"<strong>التطبيق المستقل على شاشة بمقياس عرض مُكبَّر (Windows).</strong> كانت الصفحة مُزاحة داخل النافذة، مقطوعة من اليمين والأسفل، وتنزلق خلف الإطار أثناء سحب النافذة: إذ لم تكن العملية مدركة لـ DPI، فكان Windows يمطّ النافذة بينما يرسم عرض الويب بالبكسلات الحقيقية. ويعلن التطبيق المستقل الآن الإدراك لـ DPI لكل شاشة قبل وجود أي نافذة.","changelog.df00e0d65bc5":"<strong>يُفتح التطبيق المستقل بحجم المكوّن الإضافي.</strong> يمرّر مقياس الشاشة إلى nih-plug بصفته <code>--dpi-scale</code> (ولا يزال <code>--dpi-scale</code> الصريح هو الغالب)، فيُفتح بالحجم نفسه الذي يُفتح به المحرّر ذاته داخل برنامج مضيف.","changelog.0e3c3179efba":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-24\">2026-09-24</time></span><span class=\"release__title\">F: الأساس</span>","changelog.42f5ee22d43e":"المنتج الفارغ الذي تُبنى عليه كل الدرجات اللاحقة: يُحمَّل، ويمرّر الصوت دون مساس، ويفتح محرّره، وتعمل كل بوابات الجودة.","changelog.c794a76c2618":"<strong>المكوّن الإضافي، بكل الصيغ من ملف ثنائي واحد.</strong> مكوّن إضافي CLAP مبني على nih-plug مع نقاط دخول VST3 وAUv2 يُسقطها <code>clap-wrapper</code> (نظيف الترخيص: بلا روابط VST3 بترخيص GPL)، إضافةً إلى التطبيق المستقل. ستيريو أو أحادي، وتمرير مباشر، وصفر تأخير، وحالة محفوظة ذات إصدار ترفض كل ما لا تستطيع قراءته بدلًا من إسقاط البرنامج المضيف، ومفتاح <strong>تجاوز</strong> للبرنامج المضيف، وضبط مستوى <strong>المخرج</strong> (من −24 إلى +6 dB، بانتقال ناعم).","changelog.6f91cc8aeb3f":"<strong>هيكل المحرّر.</strong> محرّر React داخل مُحوِّل webview المشترك من Freally، يُقدَّم من داخل الملف الثنائي في ظل سياسة أمان محتوى صارمة، مع جسر مُنمَّط إلى المكوّن الإضافي (طلب/استجابة إضافةً إلى أحداث تُستطلع دوريًا) تُولَّد أنواع TypeScript الخاصة به من أنواع Rust.","changelog.e6f8feb48be4":"<strong>شريط عنوان Freally.</strong> اسم المنتج بأبعاد ثلاثية (3D)، يدور إلى الخلف حول محوره Y، ثم يثبت، ثم يدور مجددًا — كما في Freally MIDI Master وFreally Oscillate، بحجم أكبر ليسهل رؤية الدوران؛ وثابت مع تقليل الحركة.","changelog.f556ccffa36f":"<strong>اتفاقية الترخيص</strong> (<code>EULA.md</code>) وبوابتها: يطلب منك Unloop قبولها عند أول فتح ويبقى خاملًا حتى تفعل. والمكوّن الإضافي الخامل يمرّر صوتك دون مساس — لا شيء يضبطه برنامج مضيف أو مشروع محفوظ، بما في ذلك ضبط مستوى المخرج، يغيّره قبل أن توافق. والقبول أو الرفض في نسخة واحدة يصل إلى كل نسخة مفتوحة فورًا، والرفض الذي تعذّر حفظه يقول ذلك بدلًا من ترك الجلسة التالية تُفتح كأنك وافقت.","changelog.b3fe519bf775":"<strong><code>THIRD-PARTY-NOTICES.md</code></strong>، مُولَّد مما يُشحن فعلًا — كل حزمة في المكوّن الإضافي والتطبيق المستقل على كل نظام تشغيل، وحزم المحرّر والخطوط، مع تراخيصها وأصحاب حقوق النشر — ومحمول في كل أرشيف إصدار مع ترخيص الخطوط (<code>OFL-Noto.txt</code>).","changelog.565020242597":"<strong>رموز التصميم والمظاهر</strong> — الداكن والفاتح والنظام — مع فحص تباين WCAG 2.1 AA في كليهما؛ وخطوط Noto مضمَّنة لكل اللغات الـ 18.","changelog.7ddbeff39e12":"<strong>18 لغة</strong> في المحرّر، مع بوابة تُبقي كل الفهارس متوافقة.","changelog.6ad657e4e2ad":"<strong>التتبّع التشخيصي</strong> (<code>UNLOOP_TRACE=all</code>، يُكتب في ملف سجل) للمشكلات التي لا تحدث إلا داخل برنامج مضيف.","changelog.594511701ab8":"<strong>أيقونات</strong> مشتقة من الأيقونة الأصلية الوحيدة لـ Windows وmacOS وLinux وموقع الوثائق.","changelog.3ad9c9b08c97":"<strong>بوابات الجودة</strong>، في <code>npm run ci:local</code> (Windows) و<code>npm run ci:linux</code> (Docker Desktop): التنسيق، والفحص الساكن (lint)، وفحوصات الأنواع، وclippy مع حظر <code>std::net</code>، واختبارات الوحدات واختبارات Playwright، واختبار لخيط الصوت يعدّ عمليات تخصيص الذاكرة، وبوابة تبعيات تمنع الذكاء الاصطناعي والشبكة والقياس عن بُعد، وسياسة التراخيص والتنبيهات الأمنية، وبوابة للإشعارات المُولَّدة، وبوابات للشيفرة المشتركة ولانحراف الروابط، وبوابة تمنع التنزيلات قبل 1.0 في موقع الوثائق، وclap-validator وpluginval (بدرجة صرامة 10). وقد رُوقبت كل بوابة وهي تفشل قبل الوثوق بها.","changelog.29509f5c50ce":"<strong>أدوات الإصدار</strong>: <code>npm run release:bundle</code> وسير عمل إصدار يعمل بالوسوم فقط، لا يحمل أي رمز كتابة أو رمز مستودع خاص أثناء تشغيله شيفرة بناء من أطراف ثالثة، ويتحقق من أن كل أرشيف هو فعلًا zip أو gzip قبل نشره.","changelog.361aee95901b":"هيكل موقع الوثائق مع سلّم الإصدارات العام.","changelog.388399ae707a":"لا يجيب جسر المحرّر إلا على طلب <code>POST</code> بصيغة JSON من المحرّر نفسه: الصفحة التي ليست من Unloop — رابط أو ملف أُفلت على النافذة — لا تستطيع استدعاءه ولا قراءة إجاباته، ولم يعد الإفلات ينقل المحرّر إلى صفحة أخرى على الإطلاق.","changelog.1f976b647d80":"لا يفتح المكوّن الإضافي في إصدار النشر أي منفذ تصحيح DevTools (خطّاف الاختبار في Freally MIDI Master، وهو الآن خلف ميزة يُبنى Unloop بدونها)، ويرفض فحص الحزمة أي ملف ثنائي قد يفتحه، أو أي ملف لم يُبنَ من المصادر المثبَّتة.","changelog.f65776baedfa":"لم يعد بإمكان التتبّع التشخيصي إسقاط البرنامج المضيف إذا اختفت وحدة الطرفية الخاصة به.","changelog.2fedafc14be7":"<strong>Linux: لم يكن المحرّر قادرًا على التواصل مع المكوّن الإضافي.</strong> كان webview يسلّم كل طلب إلى الجسر بجسم فارغ، فلم يكن ممكنًا قبول اتفاقية الترخيص أبدًا. تصل أجسام الطلبات الآن (WebKitGTK 2.40 أو أحدث).","changelog.55bda2d0ead3":"لم يعد التطبيق المستقل يرفض البدء حين يُعطى <code>-p &lt;period&gt;</code>.","changelog.bf6b0c2f06b4":"<strong>Linux: لم يعد البرنامج المضيف الذي يفحص المكوّنات الإضافية بتحميلها وإلغاء تحميلها ينهار بعد ثوانٍ قليلة.</strong> يجلب WebKitGTK الخاص بالمحرّر معه خيوط JavaScriptCore؛ وتبقى مكتبة المكوّن الإضافي الآن محمّلة حتى يخرج البرنامج المضيف (وقد كشفت ذلك اختبارات الفحص في clap-validator).","changelog.f95b9de4af46":"<strong>Linux: لم يعد إغلاق المحرّر بسرعة يُنهي البرنامج المضيف</strong> — إصلاحان في مُحوِّل webview المشترك من Freally (مصيدة لأخطاء X على خيط GTK الخاص به، وإغلاق ينتظر زوال عرض الويب). يجتاز pluginval بدرجة صرامة 10 الآن على Linux، بما في ذلك اختبارات المحرّر.","changelog.51862fa2d198":"أُصلح في المصدر الأعلى (في تفرّع nih-plug المشترك، المُستخدَم عبر <code>shared-v1</code> في Freally MIDI Master)","changelog.89bea0569ab2":"يُبلَّغ برنامج CLAP المضيف الآن بأن قيم مُعاملاته تغيّرت بعد تحميل مشروع (clap-validator <code>state-reproducibility-*</code>).","changelog.26edfb636bce":"لم يعد فتح المحرّر أو إغلاقه يحتجز قفلًا قد تعيد عملية بدء تشغيل المحرّر نفسه الدخول إليه — وهو ما كان يسبّب جمودًا تامًا في الخيط الرئيسي للبرنامج المضيف (pluginval <code>Editor Automation</code>).","changelog.e6463781d61f":"انتقل <code>rtrb</code> إلى 0.3.5، ما يُغلق RUSTSEC-2026-0274 (استخدام بعد التحرير) من مصدره بدلًا من تجاهله.","changelog.d9577706c4ec":"البرامج المضيفة: يُثبَت التحميل في FL Studio وAbleton Live وReaper يدويًا، لا عبر CI، ولا تزال صفوف مصفوفة البرامج المضيفة تلك بانتظار إنجازها في هذه الدرجة؛ وتُثبت أدوات التحقق أن المكوّن الإضافي سليم البنية، وقد شُغِّل التطبيق المستقل.","changelog.edf3e5f9658b":"AU مبني ومحزوم لكنه غير مُثبَت: لم يحمّله أي جهاز Mac بعد. ومحرّر Linux مبني ومُتحقَّق منه في حاوية لكنه لم يُستخدم بعد في جلسة Linux حقيقية.","changelog.c95891622d38":"يحتفظ مُحوِّل webview المشترك ببيانات المتصفح في مجلد يحمل اسم Freally MIDI Master إلى أن يتعلّم المُحوِّل تسمية مجلده الخاص (في خارطة الطريق)."};
